import { db } from '../firebase/config';
import { collection, getDocs, query, where, Timestamp, updateDoc, doc, deleteDoc } from 'firebase/firestore';

/**
 * Service pour gérer la remise à zéro quotidienne des alimentations et des notes
 */

// Collections
const FEEDINGS_COLLECTION = 'feedings';
const ANIMALS_COLLECTION = 'animals';

/**
 * Réinitialise les alimentations et les notes pour un nouveau jour
 * Cette fonction est appelée manuellement via le bouton "New Day"
 * @param {boolean} deleteOldFeedings - Si true, supprime complètement les feedings des jours précédents au lieu de les marquer comme "pending"
 */
export const checkAndResetFeedings = async (deleteOldFeedings = true) => {
  try {
    const now = new Date();
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    console.log('Exécution de la remise à zéro des alimentations et des notes...');
    
    // 1. Récupérer toutes les alimentations
    const feedingsRef = collection(db, FEEDINGS_COLLECTION);
    const feedingsSnapshot = await getDocs(feedingsRef);
    
    console.log(`Nombre total de feedings trouvés: ${feedingsSnapshot.size}`);
    
    // Mettre à jour les alimentations
    const feedingUpdatePromises = [];
    feedingsSnapshot.forEach((docSnapshot) => {
      const feedingRef = doc(db, FEEDINGS_COLLECTION, docSnapshot.id);
      const feedingData = docSnapshot.data();
      const feedingId = docSnapshot.id;
      
      // Vérifier si la date existe
      if (!feedingData.date) {
        console.log(`Feeding ${feedingId} n'a pas de date, ignoré`);
        return;
      }
      
      const feedingDate = feedingData.date.toDate();
      feedingDate.setHours(0, 0, 0, 0);
      const todayTime = today.getTime();
      const feedingTime = feedingDate.getTime();
      
      console.log(`Feeding ${feedingId}: date=${feedingDate.toDateString()}, status=${feedingData.status}`);
      
      // Toujours supprimer complètement les feedings
      feedingUpdatePromises.push(deleteDoc(feedingRef));
      console.log(`Feeding ${feedingId} marqué pour suppression complète`);
    });
    
    // 2. Réinitialiser les notes des animaux
    const animalsRef = collection(db, ANIMALS_COLLECTION);
    const animalsSnapshot = await getDocs(animalsRef);
    
    // Mettre à jour les notes des animaux
    const animalUpdatePromises = [];
    animalsSnapshot.forEach((docSnapshot) => {
      const animalRef = doc(db, ANIMALS_COLLECTION, docSnapshot.id);
      const animalData = docSnapshot.data();
      
      // Réinitialiser les notes quotidiennes pour tous les animaux
      animalUpdatePromises.push(updateDoc(animalRef, { 
        dailyNotes: '',
        lastFeeding: null // Réinitialiser également la dernière alimentation
      }));
    });
    
    // Exécuter toutes les mises à jour
    const allPromises = [...feedingUpdatePromises, ...animalUpdatePromises];
    await Promise.all(allPromises);
    
    // Enregistrer la date de la dernière remise à zéro
    localStorage.setItem('lastFeedingReset', now.toISOString());
    
    console.log(`Remise à zéro effectuée pour ${feedingUpdatePromises.length} alimentations et ${animalUpdatePromises.length} notes d'animaux`);
    return {
      feedingsReset: feedingUpdatePromises.length,
      notesReset: animalUpdatePromises.length
    };
  } catch (error) {
    console.error('Erreur lors de la remise à zéro des alimentations:', error);
    throw error;
  }
};

export default {
  checkAndResetFeedings
};
