/**
 * Utilitaire pour compresser les images avant l'upload
 */

/**
 * Compresse une image en réduisant sa qualité et sa taille
 * @param {File} file - Le fichier image à compresser
 * @param {Object} options - Options de compression
 * @param {number} options.maxWidth - Largeur maximale en pixels (défaut: 800)
 * @param {number} options.maxHeight - Hauteur maximale en pixels (défaut: 800)
 * @param {number} options.quality - Qualité de compression JPEG (0-1, défaut: 0.3)
 * @returns {Promise<Blob>} - Retourne une promesse avec le blob compressé
 */
export const compressImage = (file, options = {}) => {
  const maxWidth = options.maxWidth || 800;
  const maxHeight = options.maxHeight || 800;
  const quality = options.quality || 0.3; // Compression très forte (30% de qualité)

  return new Promise((resolve, reject) => {
    // Vérifier que le fichier est une image
    if (!file || !file.type.match(/image.*/)) {
      reject(new Error('Le fichier n\'est pas une image valide'));
      return;
    }

    const reader = new FileReader();
    reader.onload = (readerEvent) => {
      const image = new Image();
      image.onload = () => {
        // Calculer les dimensions pour maintenir le ratio
        let width = image.width;
        let height = image.height;
        
        if (width > height) {
          if (width > maxWidth) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          }
        } else {
          if (height > maxHeight) {
            width = Math.round((width * maxHeight) / height);
            height = maxHeight;
          }
        }
        
        // Créer un canvas pour redimensionner l'image
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        
        const ctx = canvas.getContext('2d');
        ctx.drawImage(image, 0, 0, width, height);
        
        // Convertir en blob avec compression
        canvas.toBlob((blob) => {
          if (blob) {
            // Ajouter des métadonnées au blob pour faciliter son utilisation
            blob.name = file.name;
            blob.lastModified = file.lastModified;
            
            resolve(blob);
          } else {
            reject(new Error('Échec de la compression de l\'image'));
          }
        }, 'image/jpeg', quality); // Toujours convertir en JPEG pour une meilleure compression
      };
      
      image.onerror = () => {
        reject(new Error('Impossible de charger l\'image'));
      };
      
      image.src = readerEvent.target.result;
    };
    
    reader.onerror = () => {
      reject(new Error('Impossible de lire le fichier'));
    };
    
    reader.readAsDataURL(file);
  });
};

/**
 * Compresse une image avec des paramètres spécifiques selon le type d'utilisation
 * @param {File} file - Le fichier image à compresser
 * @param {string} type - Le type d'utilisation ('profile', 'bowl', 'general')
 * @returns {Promise<Blob>} - Retourne une promesse avec le blob compressé
 */
export const compressImageByType = (file, type = 'general') => {
  const options = {
    profile: { maxWidth: 400, maxHeight: 400, quality: 0.4 },  // Photos de profil des animaux
    bowl: { maxWidth: 600, maxHeight: 600, quality: 0.3 },     // Photos des bols d'eau/nourriture
    general: { maxWidth: 800, maxHeight: 800, quality: 0.3 }   // Autres images
  };
  
  return compressImage(file, options[type] || options.general);
};

export default {
  compressImage,
  compressImageByType
};
