import { db } from './config';
import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  getDocs, 
  getDoc, 
  query, 
  where,
  orderBy,
  serverTimestamp,
  Timestamp
} from 'firebase/firestore';
import { getAnimalById } from './animalService';

// Collection pour les enregistrements d'alimentation
const FEEDINGS_COLLECTION = 'feedings';

/**
 * Récupère tous les enregistrements d'alimentation
 */
export const getAllFeedings = async (params = {}) => {
  try {
    const feedingsRef = collection(db, FEEDINGS_COLLECTION);
    
    // Construire la requête avec les filtres
    let conditions = [];
    
    // Ajouter les conditions de filtrage
    if (params.animalId) {
      console.log('Filtering by animalId:', params.animalId);
      // Vérifier si l'ID est une chaîne ou un objet
      const animalId = typeof params.animalId === 'object' && params.animalId._id ? 
        params.animalId._id : params.animalId;
      console.log('Normalized animalId for query:', animalId);
      conditions.push(where('animalId', '==', animalId));
      
      // SOLUTION TEMPORAIRE: Ne pas ajouter de tri quand on filtre par animalId
      // pour éviter l'erreur d'index manquant
      // Retirer cette condition une fois l'index créé dans Firebase
    } else {
      // Filtrer par statut si spécifié
      if (params.status && params.status !== 'all') {
        conditions.push(where('status', '==', params.status));
      }
      
      // Filtrer par date si spécifié
      if (params.startDate) {
        const startDate = new Date(params.startDate);
        conditions.push(where('date', '>=', Timestamp.fromDate(startDate)));
      }
      
      if (params.endDate) {
        const endDate = new Date(params.endDate);
        conditions.push(where('date', '<=', Timestamp.fromDate(endDate)));
      }
      
      // Ajouter le tri par date seulement si on ne filtre pas par animalId
      conditions.push(orderBy('date', 'desc'));
    }
    
    // Construire la requête finale avec toutes les conditions
    const q = query(feedingsRef, ...conditions);
    
    console.log('Fetching feedings with params:', params);
    console.log('Query conditions:', conditions);
    
    const querySnapshot = await getDocs(q);
    
    console.log('Query results count:', querySnapshot.size);
    
    // Débogage: afficher tous les documents et leurs animalId
    if (params.animalId && querySnapshot.size === 0) {
      console.log('DEBUG: No results found with animalId filter. Checking all feedings...');
      const allFeedingsRef = collection(db, FEEDINGS_COLLECTION);
      const allFeedingsQuery = query(allFeedingsRef, orderBy('date', 'desc'));
      const allFeedingsSnapshot = await getDocs(allFeedingsQuery);
      
      console.log('Total feedings in database:', allFeedingsSnapshot.size);
      allFeedingsSnapshot.forEach(doc => {
        const data = doc.data();
        console.log('Feeding ID:', doc.id, 'animalId:', data.animalId, 'date:', data.date.toDate());
      });
    }
    
    // Récupérer les données des enregistrements d'alimentation
    const feedings = [];
    const promises = [];
    
    querySnapshot.forEach((doc) => {
      const feedingData = {
        _id: doc.id,
        ...doc.data(),
        date: doc.data().date.toDate().toISOString() // Convertir Timestamp en ISO string
      };
      
      // Récupérer les données de l'animal associé
      if (feedingData.animalId) {
        const promise = getAnimalById(feedingData.animalId)
          .then(response => {
            feedingData.animal = response.data;
            return feedingData;
          })
          .catch(() => {
            // Si l'animal n'est pas trouvé, continuer sans les données de l'animal
            return feedingData;
          });
        
        promises.push(promise);
      } else {
        feedings.push(feedingData);
      }
    });
    
    // Attendre que toutes les promesses soient résolues
    const resolvedFeedings = await Promise.all(promises);
    feedings.push(...resolvedFeedings);
    
    // Si on a filtré par animalId, trier les résultats côté client
    // car on n'a pas pu utiliser orderBy dans la requête
    if (params.animalId) {
      feedings.sort((a, b) => {
        const dateA = new Date(a.date);
        const dateB = new Date(b.date);
        return dateB - dateA; // Tri décroissant (plus récent au plus ancien)
      });
      console.log('Results sorted client-side by date (desc)');
    }
    
    return { data: feedings };
  } catch (error) {
    console.error('Error getting feedings:', error);
    throw error;
  }
};

/**
 * Récupère un enregistrement d'alimentation par son ID
 */
export const getFeedingById = async (feedingId) => {
  try {
    console.log('Fetching feeding with ID:', feedingId);
    
    // Si l'ID est invalide ou manquant, essayons de récupérer le premier enregistrement
    if (!feedingId || feedingId === 'undefined' || feedingId === 'null') {
      console.log('Invalid feeding ID, trying to get the first feeding');
      const feedingsRef = collection(db, FEEDINGS_COLLECTION);
      const querySnapshot = await getDocs(feedingsRef);
      
      if (querySnapshot.empty) {
        throw new Error('No feedings found in the database');
      }
      
      // Prendre le premier enregistrement
      const firstFeedingDoc = querySnapshot.docs[0];
      console.log('Found first feeding with ID:', firstFeedingDoc.id);
      
      const firstFeedingData = {
        _id: firstFeedingDoc.id,
        ...firstFeedingDoc.data(),
        date: firstFeedingDoc.data().date.toDate().toISOString()
      };
      
      // Récupérer les données de l'animal associé
      if (firstFeedingData.animalId) {
        try {
          const animalResponse = await getAnimalById(firstFeedingData.animalId);
          firstFeedingData.animal = animalResponse.data;
        } catch (error) {
          console.error('Error getting animal for first feeding:', error);
        }
      }
      
      return { data: firstFeedingData };
    }
    
    // Sinon, récupérer l'enregistrement avec l'ID spécifié
    const feedingRef = doc(db, FEEDINGS_COLLECTION, feedingId);
    console.log('Feeding reference:', feedingRef);
    
    const feedingDoc = await getDoc(feedingRef);
    console.log('Feeding document exists?', feedingDoc.exists());
    
    if (!feedingDoc.exists()) {
      console.log('Feeding not found, trying to get the first feeding');
      
      // Si l'enregistrement n'existe pas, essayer de récupérer le premier
      const feedingsRef = collection(db, FEEDINGS_COLLECTION);
      const querySnapshot = await getDocs(feedingsRef);
      
      if (querySnapshot.empty) {
        throw new Error('No feedings found in the database');
      }
      
      // Prendre le premier enregistrement
      const firstFeedingDoc = querySnapshot.docs[0];
      console.log('Found first feeding with ID:', firstFeedingDoc.id);
      
      const firstFeedingData = {
        _id: firstFeedingDoc.id,
        ...firstFeedingDoc.data(),
        date: firstFeedingDoc.data().date.toDate().toISOString()
      };
      
      // Récupérer les données de l'animal associé
      if (firstFeedingData.animalId) {
        try {
          const animalResponse = await getAnimalById(firstFeedingData.animalId);
          firstFeedingData.animal = animalResponse.data;
        } catch (error) {
          console.error('Error getting animal for first feeding:', error);
        }
      }
      
      return { data: firstFeedingData };
    }
    
    const feedingData = {
      _id: feedingDoc.id,
      ...feedingDoc.data(),
      date: feedingDoc.data().date.toDate().toISOString() // Convertir Timestamp en ISO string
    };
    console.log('Feeding data:', feedingData);
    
    // Récupérer les données de l'animal associé
    if (feedingData.animalId) {
      try {
        const animalResponse = await getAnimalById(feedingData.animalId);
        feedingData.animal = animalResponse.data;
      } catch (error) {
        console.error('Error getting animal for feeding:', error);
      }
    }
    
    return { data: feedingData };
  } catch (error) {
    console.error('Error getting feeding:', error);
    throw error;
  }
};

/**
 * Crée un nouvel enregistrement d'alimentation
 */
export const createFeeding = async (feedingData) => {
  try {
    // Convertir les images en base64 si elles existent
    let waterBowlBase64 = null;
    let foodBowlBase64 = null;
    
    if (feedingData.waterBowl) {
      const reader = new FileReader();
      const promise = new Promise((resolve) => {
        reader.onload = (e) => {
          waterBowlBase64 = e.target.result;
          resolve();
        };
        reader.readAsDataURL(feedingData.waterBowl);
      });
      await promise;
    }
    
    if (feedingData.foodBowl) {
      const reader = new FileReader();
      const promise = new Promise((resolve) => {
        reader.onload = (e) => {
          foodBowlBase64 = e.target.result;
          resolve();
        };
        reader.readAsDataURL(feedingData.foodBowl);
      });
      await promise;
    }
    
    // S'assurer que la date d'alimentation est aujourd'hui
    const now = new Date();
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    const feedingDate = new Date(feedingData.date);
    feedingDate.setHours(0, 0, 0, 0);
    
    // Si la date d'alimentation n'est pas aujourd'hui, la forcer à aujourd'hui
    if (feedingDate.getTime() !== today.getTime()) {
      console.log('Forcing feeding date to today');
      feedingData.date = now.toISOString();
    }
    
    // Vérifier si un enregistrement existe déjà pour cet animal aujourd'hui
    const feedingsRef = collection(db, FEEDINGS_COLLECTION);
    const q = query(
      feedingsRef,
      where('animalId', '==', feedingData.animalId)
    );
    
    const querySnapshot = await getDocs(q);
    
    // Vérifier si un enregistrement existe déjà pour aujourd'hui
    const existingFeeding = querySnapshot.docs.find(doc => {
      const docDate = doc.data().date.toDate();
      docDate.setHours(0, 0, 0, 0);
      return docDate.getTime() === today.getTime();
    });
    
    if (existingFeeding) {
      // Si un feeding existe déjà aujourd'hui, on le met à jour au lieu d'en créer un nouveau
      console.log('Updating existing feeding for today');
      const existingFeedingId = existingFeeding.id;
      return updateFeeding(existingFeedingId, feedingData);
    }
    
    // Normaliser l'ID de l'animal (s'assurer qu'il s'agit d'une chaîne)
    const normalizedAnimalId = typeof feedingData.animalId === 'object' && feedingData.animalId._id ? 
      feedingData.animalId._id : feedingData.animalId;
    
    // Préparer les données pour Firestore
    const feedingToSave = {
      animalId: normalizedAnimalId,
      date: Timestamp.fromDate(new Date(feedingData.date)),
      status: feedingData.status || 'completed',
      notes: feedingData.notes || '',
      waterBowlImage: waterBowlBase64,
      foodBowlImage: foodBowlBase64,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp()
    };
    
    console.log('Creating feeding with animalId:', normalizedAnimalId, '(original:', feedingData.animalId, ')');
    console.log('Animal ID type:', typeof normalizedAnimalId);
    
    const docRef = await addDoc(collection(db, FEEDINGS_COLLECTION), feedingToSave);
    
    // Récupérer l'animal associé
    let animal = null;
    try {
      const animalResponse = await getAnimalById(feedingData.animalId);
      animal = animalResponse.data;
    } catch (error) {
      console.error('Error getting animal for new feeding:', error);
    }
    
    return { 
      data: {
        _id: docRef.id,
        ...feedingToSave,
        date: feedingToSave.date.toDate().toISOString(),
        animal
      }
    };
  } catch (error) {
    console.error('Error creating feeding:', error);
    throw error;
  }
};

/**
 * Met à jour un enregistrement d'alimentation existant
 */
export const updateFeeding = async (feedingId, feedingData) => {
  try {
    const feedingRef = doc(db, FEEDINGS_COLLECTION, feedingId);
    
    // Convertir les images en base64 si elles existent
    let waterBowlBase64 = null;
    let foodBowlBase64 = null;
    
    if (feedingData.waterBowl && (feedingData.waterBowl instanceof File || feedingData.waterBowl instanceof Blob)) {
      console.log('Conversion de l\'image du bol d\'eau en base64...');
      const reader = new FileReader();
      const promise = new Promise((resolve, reject) => {
        reader.onload = (e) => {
          waterBowlBase64 = e.target.result;
          console.log('Image du bol d\'eau convertie en base64');
          resolve();
        };
        reader.onerror = (e) => {
          console.error('Erreur lors de la conversion de l\'image du bol d\'eau:', e);
          reject(e);
        };
        reader.readAsDataURL(feedingData.waterBowl);
      });
      await promise;
    }
    
    if (feedingData.foodBowl && (feedingData.foodBowl instanceof File || feedingData.foodBowl instanceof Blob)) {
      console.log('Conversion de l\'image du bol de nourriture en base64...');
      const reader = new FileReader();
      const promise = new Promise((resolve, reject) => {
        reader.onload = (e) => {
          foodBowlBase64 = e.target.result;
          console.log('Image du bol de nourriture convertie en base64');
          resolve();
        };
        reader.onerror = (e) => {
          console.error('Erreur lors de la conversion de l\'image du bol de nourriture:', e);
          reject(e);
        };
        reader.readAsDataURL(feedingData.foodBowl);
      });
      await promise;
    }
    
    // Préparer les données pour Firestore
    const feedingToUpdate = {
      animalId: feedingData.animalId,
      status: feedingData.status || 'completed',
      notes: feedingData.notes || '',
      updatedAt: serverTimestamp()
    };
    
    // Ajouter la date si elle est fournie
    if (feedingData.date) {
      feedingToUpdate.date = Timestamp.fromDate(new Date(feedingData.date));
    }
    
    // Ajouter les images si elles ont été modifiées
    if (waterBowlBase64) {
      console.log('Mise à jour de l\'image du bol d\'eau');
      feedingToUpdate.waterBowlImage = waterBowlBase64;
    } else if (feedingData.clearWaterBowl) {
      // Si l'utilisateur veut explicitement vider l'image du bol d'eau
      console.log('Suppression de l\'image du bol d\'eau');
      feedingToUpdate.waterBowlImage = null;
    }
    
    if (foodBowlBase64) {
      console.log('Mise à jour de l\'image du bol de nourriture');
      feedingToUpdate.foodBowlImage = foodBowlBase64;
    } else if (feedingData.clearFoodBowl) {
      // Si l'utilisateur veut explicitement vider l'image du bol de nourriture
      console.log('Suppression de l\'image du bol de nourriture');
      feedingToUpdate.foodBowlImage = null;
    }
    
    console.log('Données de mise à jour du feeding:', {
      ...feedingToUpdate,
      waterBowlImage: feedingToUpdate.waterBowlImage ? 'Image présente' : 'Pas d\'image',
      foodBowlImage: feedingToUpdate.foodBowlImage ? 'Image présente' : 'Pas d\'image'
    });
    
    // Ces lignes sont redondantes avec la logique ci-dessus et peuvent causer des conflits
    // Nous les supprimons pour éviter les problèmes
    
    console.log('Mise à jour du document Firestore avec les données suivantes:', {
      ...feedingToUpdate,
      waterBowlImage: feedingToUpdate.waterBowlImage ? 'Image présente (base64)' : 'Pas d\'image',
      foodBowlImage: feedingToUpdate.foodBowlImage ? 'Image présente (base64)' : 'Pas d\'image'
    });
    
    await updateDoc(feedingRef, feedingToUpdate);
    
    // Récupérer l'enregistrement d'alimentation mis à jour
    const updatedFeeding = await getDoc(feedingRef);
    const feedingDataUpdated = {
      _id: updatedFeeding.id,
      ...updatedFeeding.data(),
      date: updatedFeeding.data().date.toDate().toISOString()
    };
    
    // Récupérer l'animal associé
    let animal = null;
    try {
      const animalResponse = await getAnimalById(feedingDataUpdated.animalId);
      animal = animalResponse.data;
    } catch (error) {
      console.error('Error getting animal for updated feeding:', error);
    }
    
    feedingDataUpdated.animal = animal;
    
    return { data: feedingDataUpdated };
  } catch (error) {
    console.error('Error updating feeding:', error);
    throw error;
  }
};

/**
 * Supprime un enregistrement d'alimentation
 */
export const deleteFeeding = async (feedingId) => {
  try {
    await deleteDoc(doc(db, FEEDINGS_COLLECTION, feedingId));
    return { success: true };
  } catch (error) {
    console.error('Error deleting feeding:', error);
    throw error;
  }
};

/**
 * Récupère tous les enregistrements d'alimentation pour aujourd'hui
 */
export const getTodayFeedings = async () => {
  try {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    
    const feedingsRef = collection(db, FEEDINGS_COLLECTION);
    const q = query(
      feedingsRef,
      where('date', '>=', Timestamp.fromDate(today)),
      where('date', '<', Timestamp.fromDate(tomorrow))
    );
    
    const querySnapshot = await getDocs(q);
    const feedings = [];
    
    querySnapshot.forEach((doc) => {
      feedings.push({
        _id: doc.id,
        ...doc.data()
      });
    });
    
    return {
      success: true,
      data: feedings
    };
  } catch (error) {
    console.error('Error getting today\'s feedings:', error);
    return {
      success: false,
      error: error.message
    };
  }
};
