import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Button, 
  TextField, 
  Typography, 
  Paper, 
  Grid, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  FormHelperText,
  CircularProgress,
  Divider,
  useTheme,
  IconButton,
  Avatar,
  Card,
  CardContent,
  CardMedia,
  Chip,
  FormControlLabel,
  Checkbox,
  InputAdornment,
  Tooltip,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
} from '@mui/material';
import { 
  Save as SaveIcon, 
  ArrowBack as ArrowBackIcon,
  Delete as DeleteIcon,
  CameraAlt as CameraAltIcon,
  PhotoCamera as PhotoCameraIcon,
  Restaurant as RestaurantIcon,
  Person as PersonIcon,
  Info as InfoIcon,
  Pets as PetsIcon,
} from '@mui/icons-material';
import { useNavigate, useParams, useSearchParams, Link, useLocation } from 'react-router-dom';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import { getAnimalById, getAnimals } from '../api/api';
import { createFeeding, getFeedingById, updateFeeding } from '../api/api';
import ConfirmationDialog from '../components/common/ConfirmationDialog';
import ImageViewerModal from '../components/common/ImageViewerModal';
import format from 'date-fns/format';
import { compressImageByType } from '../utils/imageCompression';

const validationSchema = Yup.object({
  animal: Yup.string().required('Animal is required'),
  date: Yup.date().required('Date is required'),
  time: Yup.string().required('Time is required'),
  status: Yup.string().required('Status is required'),
  notes: Yup.string(),
});

const FeedingForm = ({ isEdit = false }) => {
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const theme = useTheme();
  const [loading, setLoading] = useState(isEdit);
  const [animals, setAnimals] = useState([]);
  const [selectedAnimal, setSelectedAnimal] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [waterBowlImage, setWaterBowlImage] = useState(null);
  const [foodBowlImage, setFoodBowlImage] = useState(null);
  const [waterBowlPreview, setWaterBowlPreview] = useState('');
  const [foodBowlPreview, setFoodBowlPreview] = useState('');
  const [imageViewerOpen, setImageViewerOpen] = useState(false);
  const [currentImage, setCurrentImage] = useState({ url: '', title: '' });

  // Cleanup des URLs d'aperçu quand elles changent ou au démontage
  useEffect(() => {
    return () => {
      if (waterBowlPreview && waterBowlPreview.startsWith('blob:')) {
        URL.revokeObjectURL(waterBowlPreview);
      }
      if (foodBowlPreview && foodBowlPreview.startsWith('blob:')) {
        URL.revokeObjectURL(foodBowlPreview);
      }
    };
  }, [waterBowlPreview, foodBowlPreview]);

  const formik = useFormik({
    initialValues: {
      animal: '',
      date: format(new Date(), 'yyyy-MM-dd'),
      time: format(new Date(), 'HH:mm'),
      status: 'completed',
      notes: '',
      waterBowl: null,
      foodBowl: null,
      clearWaterBowl: false,
      clearFoodBowl: false
    },
    validationSchema,
    onSubmit: async (values) => {
      try {
        setLoading(true);
        
        // Format date and time
        const dateTime = new Date(`${values.date}T${values.time}`);
        
        // Préparer les données pour Firebase
        // S'assurer que l'ID de l'animal est une chaîne
        const animalId = String(values.animal);
        console.log('Creating feeding with animalId:', animalId, 'type:', typeof animalId);
        
        const feedingData = {
          animalId: animalId,
          date: dateTime.toISOString(),
          status: values.status,
          notes: values.notes || '',
        };
        
        // Ajouter les images si elles existent
        if (values.waterBowl instanceof File || values.waterBowl instanceof Blob) {
          console.log('Ajout de l\'image du bol d\'eau au formulaire (type: ' + typeof values.waterBowl + ')');
          feedingData.waterBowl = values.waterBowl;
          // S'assurer que le flag de suppression est désactivé si une nouvelle image est ajoutée
          feedingData.clearWaterBowl = false;
        } 
        
        // Gérer explicitement la suppression des images
        if (values.clearWaterBowl) {
          console.log('Demande de suppression de l\'image du bol d\'eau');
          feedingData.clearWaterBowl = true;
          // S'assurer qu'aucune image n'est envoyée si on demande la suppression
          delete feedingData.waterBowl;
        }
        
        if (values.foodBowl instanceof File || values.foodBowl instanceof Blob) {
          console.log('Ajout de l\'image du bol de nourriture au formulaire (type: ' + typeof values.foodBowl + ')');
          feedingData.foodBowl = values.foodBowl;
          // S'assurer que le flag de suppression est désactivé si une nouvelle image est ajoutée
          feedingData.clearFoodBowl = false;
        } 
        
        if (values.clearFoodBowl) {
          console.log('Demande de suppression de l\'image du bol de nourriture');
          feedingData.clearFoodBowl = true;
          // S'assurer qu'aucune image n'est envoyée si on demande la suppression
          delete feedingData.foodBowl;
        }
        
        console.log('Données du formulaire à envoyer:', {
          ...feedingData,
          waterBowl: feedingData.waterBowl ? 'Image présente' : 'Pas d\'image',
          foodBowl: feedingData.foodBowl ? 'Image présente' : 'Pas d\'image',
          clearWaterBowl: feedingData.clearWaterBowl,
          clearFoodBowl: feedingData.clearFoodBowl
        });
        
        if (isEdit) {
          console.log('Mise à jour du feeding avec ID:', id);
          const result = await updateFeeding(id, feedingData);
          console.log('Résultat de la mise à jour:', result);
        } else {
          console.log('Création d\'un nouveau feeding');
          await createFeeding(feedingData);
        }
        
        navigate('/feedings');
      } catch (error) {
        console.error('Error saving feeding:', error);
      } finally {
        setLoading(false);
      }
    },
  });

  // Fetch animals for the dropdown
  useEffect(() => {
    const fetchAnimals = async () => {
      try {
        const response = await getAnimals();
        setAnimals(response.data || []);
        
        // If animalId is in URL params, set it in the form
        const animalId = searchParams.get('animalId');
        if (animalId) {
          formik.setFieldValue('animal', animalId);
          fetchAnimal(animalId);
        }
      } catch (error) {
        console.error('Error fetching animals:', error);
      }
    };
    
    fetchAnimals();
  }, []);

  // Fetch feeding data if in edit mode
  useEffect(() => {
    if (isEdit && id) {
      const fetchFeeding = async () => {
        try {
          setLoading(true);
          const response = await getFeedingById(id);
          const feeding = response.data;
          
          // Format date and time from ISO string
          const feedingDate = new Date(feeding.date);
          const formattedDate = format(feedingDate, 'yyyy-MM-dd');
          const formattedTime = format(feedingDate, 'HH:mm');
          
          formik.setValues({
            animal: feeding.animal?._id || '',
            date: formattedDate,
            time: formattedTime,
            status: feeding.status || 'completed',
            notes: feeding.notes || '',
            waterBowl: null,
            foodBowl: null,
            clearWaterBowl: false,
            clearFoodBowl: false
          });
          
          // Set image previews if they exist
          if (feeding.waterBowlImage) {
            // L'image est déjà en base64 dans Firebase
            setWaterBowlPreview(feeding.waterBowlImage);
          }
          
          if (feeding.foodBowlImage) {
            // L'image est déjà en base64 dans Firebase
            setFoodBowlPreview(feeding.foodBowlImage);
          }
          
          // Fetch animal details
          if (feeding.animal?._id) {
            fetchAnimal(feeding.animal._id);
          }
        } catch (error) {
          console.error('Error fetching feeding:', error);
          navigate('/feedings');
        } finally {
          setLoading(false);
        }
      };
      
      fetchFeeding();
    }
  }, [id, isEdit, navigate]);

  const fetchAnimal = async (animalId) => {
    try {
      const response = await getAnimalById(animalId);
      setSelectedAnimal(response.data);
    } catch (error) {
      console.error('Error fetching animal:', error);
    }
  };

  const handleAnimalChange = (event) => {
    const animalId = event.target.value;
    formik.setFieldValue('animal', animalId);
    fetchAnimal(animalId);
  };

  const handleImageChange = async (field, event) => {
    const file = event.target.files[0];
    if (file) {
      console.log(`Nouvelle image sélectionnée pour ${field}:`, file.name);
      
      // En mode édition, s'assurer que les flags de suppression sont réinitialisés
      if (isEdit) {
        if (field === 'waterBowl') {
          formik.setFieldValue('clearWaterBowl', false);
        } else if (field === 'foodBowl') {
          formik.setFieldValue('clearFoodBowl', false);
        }
      }
      try {
        // Aperçu immédiat robuste (incluant JPG) via URL.createObjectURL
        const previewUrl = URL.createObjectURL(file);
        if (field === 'waterBowl') {
          setWaterBowlPreview((prev) => {
            if (prev && prev.startsWith('blob:')) URL.revokeObjectURL(prev);
            return previewUrl;
          });
        } else {
          setFoodBowlPreview((prev) => {
            if (prev && prev.startsWith('blob:')) URL.revokeObjectURL(prev);
            return previewUrl;
          });
        }
        
        // Compresser l'image en arrière-plan
        console.log(`Compression de l'image du ${field === 'waterBowl' ? 'bol d\'eau' : 'bol de nourriture'}...`);
        const compressedImage = await compressImageByType(file, 'bowl');
        
        // Set the compressed file in formik values
        formik.setFieldValue(field, compressedImage);
        console.log(`Image du ${field === 'waterBowl' ? 'bol d\'eau' : 'bol de nourriture'} compressée avec succès`);
        console.log('Valeur du champ dans formik après compression:', field, formik.values[field] ? 'Image présente' : 'Pas d\'image');

        // Mettre à jour l'aperçu pour refléter l'image compressée
        const compressedPreviewUrl = URL.createObjectURL(compressedImage);
        if (field === 'waterBowl') {
          setWaterBowlPreview((prev) => {
            if (prev && prev.startsWith('blob:')) URL.revokeObjectURL(prev);
            return compressedPreviewUrl;
          });
        } else {
          setFoodBowlPreview((prev) => {
            if (prev && prev.startsWith('blob:')) URL.revokeObjectURL(prev);
            return compressedPreviewUrl;
          });
        }
      } catch (error) {
        console.error(`Erreur lors de la compression de l'image du ${field === 'waterBowl' ? 'bol d\'eau' : 'bol de nourriture'}:`, error);
        // En cas d'échec, utiliser l'image originale
        formik.setFieldValue(field, file);
      }
    }
  };

  const handleRemoveImage = (type) => {
    if (type === 'waterBowl') {
      setWaterBowlPreview(null);
      formik.setFieldValue('waterBowl', null);
      
      // Si nous sommes en mode édition, indiquer que l'image doit être supprimée
      if (isEdit) {
        formik.setFieldValue('clearWaterBowl', true);
      }
    } else if (type === 'foodBowl') {
      setFoodBowlPreview(null);
      formik.setFieldValue('foodBowl', null);
      
      // Si nous sommes en mode édition, indiquer que l'image doit être supprimée
      if (isEdit) {
        formik.setFieldValue('clearFoodBowl', true);
      }
    }
  };

  const handleDeleteClick = () => {
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    // Handle delete logic here if needed
    console.log('Deleting feeding:', id);
    setDeleteDialogOpen(false);
    navigate('/feedings');
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Box display="flex" alignItems="center" mb={3}>
        <IconButton component={Link} to="/feedings" sx={{ mr: 1 }}>
          <ArrowBackIcon />
        </IconButton>
        <Typography variant="h5" component="h1">
          {isEdit ? 'Edit Feeding Record' : 'New Feeding Record'}
        </Typography>
        <Box flexGrow={1} />
        {isEdit && (
          <Button
            variant="outlined"
            color="error"
            startIcon={<DeleteIcon />}
            onClick={handleDeleteClick}
            sx={{ ml: 2 }}
          >
            Delete
          </Button>
        )}
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Paper elevation={2} sx={{ p: 3, borderRadius: 2, mb: 3 }}>
            <form onSubmit={formik.handleSubmit}>
              <Grid container spacing={3}>
                <Grid item xs={12} sm={6}>
                  <FormControl 
                    fullWidth 
                    margin="normal"
                    error={formik.touched.animal && Boolean(formik.errors.animal)}
                    sx={{ width: '10em' }}
                  >
                    <InputLabel id="animal-label">Animal *</InputLabel>
                    <Select
                      labelId="animal-label"
                      id="animal"
                      name="animal"
                      value={formik.values.animal}
                      onChange={handleAnimalChange}
                      onBlur={formik.handleBlur}
                      label="Animal *"
                      sx={{ minWidth: '100%' }}
                    >
                      {animals.map((animal) => (
                        <MenuItem key={animal._id} value={animal._id}>
                          {animal.name}
                        </MenuItem>
                      ))}
                    </Select>
                    {formik.touched.animal && formik.errors.animal && (
                      <FormHelperText>{formik.errors.animal}</FormHelperText>
                    )}
                  </FormControl>
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <FormControl 
                    fullWidth 
                    margin="normal"
                    error={formik.touched.status && Boolean(formik.errors.status)}
                    sx={{ minWidth: '100%' }}
                  >
                    <InputLabel id="status-label">Status *</InputLabel>
                    <Select
                      labelId="status-label"
                      id="status"
                      name="status"
                      value={formik.values.status}
                      onChange={formik.handleChange}
                      onBlur={formik.handleBlur}
                      label="Status *"
                      sx={{ minWidth: '100%' }}
                    >
                      <MenuItem value="completed">Completed</MenuItem>
                      <MenuItem value="pending">Pending</MenuItem>
                      <MenuItem value="missed">Missed</MenuItem>
                    </Select>
                    {formik.touched.status && formik.errors.status && (
                      <FormHelperText>{formik.errors.status}</FormHelperText>
                    )}
                  </FormControl>
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    id="date"
                    name="date"
                    label="Date *"
                    type="date"
                    value={formik.values.date}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.date && Boolean(formik.errors.date)}
                    helperText={formik.touched.date && formik.errors.date}
                    margin="normal"
                    InputLabelProps={{
                      shrink: true,
                    }}
                    sx={{ minWidth: '100%' }}
                  />
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    id="time"
                    name="time"
                    label="Time *"
                    type="time"
                    value={formik.values.time}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.time && Boolean(formik.errors.time)}
                    helperText={formik.touched.time && formik.errors.time}
                    margin="normal"
                    InputLabelProps={{
                      shrink: true,
                    }}
                    inputProps={{
                      step: 300, // 5 min
                    }}
                    sx={{ minWidth: '100%' }}
                  />
                </Grid>
                
                
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    id="notes"
                    name="notes"
                    label="Notes"
                    value={formik.values.notes}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    margin="normal"
                    multiline
                    rows={3}
                    placeholder="Any additional notes about the feeding..."
                    sx={{ minWidth: '100%' }}
                  />
                </Grid>
                
                <Grid item xs={12}>
                  <Divider sx={{ my: 2 }} />
                  <Box display="flex" justifyContent="flex-end" gap={2}>
                    <Button
                      type="submit"
                      variant="contained"
                      color="primary"
                      startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <SaveIcon />}
                      disabled={loading}
                    >
                      {isEdit ? 'Update' : 'Save'} Record
                    </Button>
                  </Box>
                </Grid>
              </Grid>
            </form>
          </Paper>
        </Grid>
        
        <Grid item xs={12}>
          <Typography variant="h6" gutterBottom>
            Bowl Images
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Card elevation={2} sx={{ borderRadius: 2, height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle1" gutterBottom>
                    Water Bowl
                  </Typography>
                  <Divider sx={{ mb: 2 }} />
                  
                  <Box 
                    sx={{
                      border: '1px dashed',
                      borderColor: 'divider',
                      borderRadius: 1,
                      p: 2,
                      textAlign: 'center',
                      cursor: 'pointer',
                      position: 'relative',
                      height: 200,
                      display: 'flex',
                      flexDirection: 'column',
                      justifyContent: 'center',
                      alignItems: 'center',
                      backgroundColor: 'action.hover',
                      '&:hover': {
                        backgroundColor: 'action.selected',
                      },
                    }}
                    onClick={(e) => {
                      e.stopPropagation();
                      // Ne rien faire ici car nous avons des boutons spécifiques
                    }}
                  >
                    {waterBowlPreview ? (
                      <>
                        <img
                          src={waterBowlPreview}
                          alt="Water bowl"
                          style={{
                            maxWidth: '100%',
                            maxHeight: '180px',
                            objectFit: 'contain',
                            cursor: 'zoom-in'
                          }}
                          onClick={(e) => {
                            e.stopPropagation();
                            setCurrentImage({ url: waterBowlPreview, title: 'Water Bowl Image' });
                            setImageViewerOpen(true);
                          }}
                        />
                        <Box
                          sx={{
                            position: 'absolute',
                            top: 8,
                            right: 8,
                            backgroundColor: 'rgba(0, 0, 0, 0.5)',
                            borderRadius: '50%',
                            width: 32,
                            height: 32,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: 'white',
                            '&:hover': {
                              backgroundColor: 'rgba(0, 0, 0, 0.7)',
                            },
                          }}
                          onClick={(e) => {
                            e.stopPropagation();
                            handleRemoveImage('waterBowl');
                          }}
                        >
                          <DeleteIcon fontSize="small" />
                        </Box>
                      </>
                    ) : (
                      <>
                        <PhotoCameraIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 1 }} />
                        <Typography variant="body2" color="textSecondary">
                          Take or upload water bowl photo
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                          <Button 
                            size="small" 
                            variant="outlined" 
                            startIcon={<CameraAltIcon />}
                            onClick={(e) => {
                              e.stopPropagation();
                              const input = document.getElementById('water-bowl-upload');
                              input.setAttribute('capture', 'environment');
                              input.click();
                            }}
                          >
                            Camera
                          </Button>
                          <Button 
                            size="small" 
                            variant="outlined"
                            onClick={(e) => {
                              e.stopPropagation();
                              const input = document.getElementById('water-bowl-upload');
                              input.removeAttribute('capture');
                              input.click();
                            }}
                          >
                            Gallery
                          </Button>
                        </Box>

                      </>
                    )}
                    <input
                      type="file"
                      id="water-bowl-upload"
                      accept="image/jpeg,image/jpg,image/png,image/webp,image/heic,image/heif"
                      capture="environment"
                      style={{ display: 'none' }}
                      onChange={(e) => handleImageChange('waterBowl', e)}
                    />
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Card elevation={2} sx={{ borderRadius: 2, height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle1" gutterBottom>
                    Food Bowl
                  </Typography>
                  <Divider sx={{ mb: 2 }} />
                  
                  <Box 
                    sx={{
                      border: '1px dashed',
                      borderColor: 'divider',
                      borderRadius: 1,
                      p: 2,
                      textAlign: 'center',
                      cursor: 'pointer',
                      position: 'relative',
                      height: 200,
                      display: 'flex',
                      flexDirection: 'column',
                      justifyContent: 'center',
                      alignItems: 'center',
                      backgroundColor: 'action.hover',
                      '&:hover': {
                        backgroundColor: 'action.selected',
                      },
                    }}
                    onClick={(e) => {
                      e.stopPropagation();
                      // Ne rien faire ici car nous avons des boutons spécifiques
                    }}
                  >
                    {foodBowlPreview ? (
                      <>
                        <img
                          src={foodBowlPreview}
                          alt="Food bowl"
                          style={{
                            maxWidth: '100%',
                            maxHeight: '180px',
                            objectFit: 'contain',
                            cursor: 'zoom-in'
                          }}
                          onClick={(e) => {
                            e.stopPropagation();
                            setCurrentImage({ url: foodBowlPreview, title: 'Food Bowl Image' });
                            setImageViewerOpen(true);
                          }}
                        />
                        <Box
                          sx={{
                            position: 'absolute',
                            top: 8,
                            right: 8,
                            backgroundColor: 'rgba(0, 0, 0, 0.5)',
                            borderRadius: '50%',
                            width: 32,
                            height: 32,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: 'white',
                            '&:hover': {
                              backgroundColor: 'rgba(0, 0, 0, 0.7)',
                            },
                          }}
                          onClick={(e) => {
                            e.stopPropagation();
                            handleRemoveImage('foodBowl');
                          }}
                        >
                          <DeleteIcon fontSize="small" />
                        </Box>
                      </>
                    ) : (
                      <>
                        <PhotoCameraIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 1 }} />
                        <Typography variant="body2" color="textSecondary">
                          Take or upload food bowl photo
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                          <Button 
                            size="small" 
                            variant="outlined" 
                            startIcon={<CameraAltIcon />}
                            onClick={(e) => {
                              e.stopPropagation();
                              const input = document.getElementById('food-bowl-upload');
                              input.setAttribute('capture', 'environment');
                              input.click();
                            }}
                          >
                            Camera
                          </Button>
                          <Button 
                            size="small" 
                            variant="outlined"
                            onClick={(e) => {
                              e.stopPropagation();
                              const input = document.getElementById('food-bowl-upload');
                              input.removeAttribute('capture');
                              input.click();
                            }}
                          >
                            Gallery
                          </Button>
                        </Box>
                        <Typography variant="caption" color="textSecondary" sx={{ mt: 1 }}>
                          (Max size: 5MB, will be compressed)
                        </Typography>
                      </>
                    )}
                    <input
                      type="file"
                      id="food-bowl-upload"
                      accept="image/jpeg,image/jpg,image/png,image/webp,image/heic,image/heif"
                      capture="environment"
                      style={{ display: 'none' }}
                      onChange={(e) => handleImageChange('foodBowl', e)}
                    />
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        </Grid>
      </Grid>

      <ConfirmationDialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Delete Feeding Record"
        content="Are you sure you want to delete this feeding record? This action cannot be undone."
        confirmText="Delete"
        confirmColor="error"
      />
      
      <ImageViewerModal
        open={imageViewerOpen}
        onClose={() => setImageViewerOpen(false)}
        imageUrl={currentImage.url}
        title={currentImage.title}
      />
    </Box>
  );
};

export default FeedingForm;
