/**
 * Service pour générer des images d'animaux par défaut en fonction de leur espèce
 */

// Images génériques pour chaque espèce (URLs d'images libres de droits)
const speciesImages = {
  'CHEETAH': 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?w=500&auto=format&fit=crop',
  'LEOPARD': 'https://images.unsplash.com/photo-1456926631375-92c8ce872def?w=500&auto=format&fit=crop',
  'CARACAL': 'https://images.unsplash.com/photo-1589652717406-1c69efaf1ff8?w=500&auto=format&fit=crop',
  'BLACK FOOTED CAT': 'https://images.unsplash.com/photo-1518288774672-b94e808873ff?w=500&auto=format&fit=crop',
  'SERVAL': 'https://images.unsplash.com/photo-1589308726544-51acd516f9e0?w=500&auto=format&fit=crop',
  'GENETS': 'https://images.unsplash.com/photo-1602491453631-e2a5ad90a131?w=500&auto=format&fit=crop',
  'AFRICAN WILD CAT': 'https://images.unsplash.com/photo-1573865526739-10659fec78a5?w=500&auto=format&fit=crop',
  'LION': 'https://images.unsplash.com/photo-1546182970-93ce21c322ad?w=500&auto=format&fit=crop',
  // Image par défaut pour les espèces non listées
  'DEFAULT': 'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=500&auto=format&fit=crop',
};

/**
 * Récupère une image par défaut pour une espèce donnée
 * @param {string} species - L'espèce de l'animal
 * @returns {Promise<string>} - L'image en base64
 */
export const getDefaultImageForSpecies = async (species) => {
  try {
    const imageUrl = speciesImages[species] || speciesImages['DEFAULT'];
    const response = await fetch(imageUrl);
    const blob = await response.blob();
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.error('Error fetching default image:', error);
    return null;
  }
};

/**
 * Génère une couleur aléatoire pour un avatar
 * @returns {string} - Une couleur hexadécimale
 */
export const getRandomColor = () => {
  const colors = [
    '#f44336', '#e91e63', '#9c27b0', '#673ab7', '#3f51b5',
    '#2196f3', '#03a9f4', '#00bcd4', '#009688', '#4caf50',
    '#8bc34a', '#cddc39', '#ffeb3b', '#ffc107', '#ff9800',
    '#ff5722', '#795548', '#607d8b'
  ];
  return colors[Math.floor(Math.random() * colors.length)];
};

/**
 * Génère les initiales d'un nom
 * @param {string} name - Le nom de l'animal
 * @returns {string} - Les initiales
 */
export const getInitials = (name) => {
  if (!name) return '?';
  return name.charAt(0).toUpperCase();
};

export default {
  getDefaultImageForSpecies,
  getRandomColor,
  getInitials
};
