import React, { useState } from 'react';
import { 
  Button, 
  Dialog, 
  DialogActions, 
  DialogContent, 
  DialogContentText, 
  DialogTitle,
  CircularProgress,
  Alert,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Typography,
  Box
} from '@mui/material';
import { 
  Pets as PetsIcon,
  Check as CheckIcon,
  Error as ErrorIcon
} from '@mui/icons-material';
import { initializeAnimals } from '../../utils/initializeAnimals';

const InitializeAnimalsButton = () => {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState([]);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');

  const handleOpen = () => {
    setOpen(true);
    setResults([]);
    setSuccess(false);
    setError('');
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleInitialize = async () => {
    try {
      setLoading(true);
      setSuccess(false);
      setError('');
      setResults([]);
      
      const initResults = await initializeAnimals();
      setResults(initResults);
      
      const successCount = initResults.filter(r => r.success).length;
      if (successCount === initResults.length) {
        setSuccess(true);
      } else if (successCount > 0) {
        setSuccess(true);
        setError(`${initResults.length - successCount} animals failed to initialize.`);
      } else {
        setError('Failed to initialize animals.');
      }
    } catch (err) {
      console.error('Error initializing animals:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Button 
        variant="contained" 
        color="secondary" 
        onClick={handleOpen}
        startIcon={<PetsIcon />}
        sx={{ ml: 2 }}
      >
        Initialize Zoo Animals
      </Button>
      
      <Dialog 
        open={open} 
        onClose={handleClose}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>Initialize Zoo Animals</DialogTitle>
        <DialogContent>
          <DialogContentText>
            This will create 29 animals in your Firebase database. This operation cannot be undone.
          </DialogContentText>
          
          {loading && (
            <Box display="flex" justifyContent="center" my={3}>
              <CircularProgress />
            </Box>
          )}
          
          {success && (
            <Alert severity="success" sx={{ mt: 2 }}>
              Animals initialized successfully!
            </Alert>
          )}
          
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
          
          {results.length > 0 && (
            <Box mt={3}>
              <Typography variant="subtitle1" gutterBottom>
                Results:
              </Typography>
              <List dense sx={{ maxHeight: 300, overflow: 'auto' }}>
                {results.map((result, index) => (
                  <ListItem key={index}>
                    <ListItemIcon>
                      {result.success ? 
                        <CheckIcon color="success" /> : 
                        <ErrorIcon color="error" />
                      }
                    </ListItemIcon>
                    <ListItemText 
                      primary={result.name} 
                      secondary={result.success ? `ID: ${result.id}` : `Error: ${result.error}`}
                    />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Close</Button>
          <Button 
            onClick={handleInitialize} 
            color="primary" 
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} /> : null}
            variant="contained"
          >
            {loading ? 'Initializing...' : 'Initialize Animals'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default InitializeAnimalsButton;
