import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Typography, 
  Button, 
  Paper, 
  Table, 
  TableBody, 
  TableCell, 
  TableContainer, 
  TableHead, 
  TableRow,
  TablePagination,
  Chip,
  CircularProgress,
  Divider,
  Grid,
  Card,
  CardContent,
  CardActionArea,
  IconButton,
  Tooltip,
  Alert,
  useTheme,
  useMediaQuery,
  Tab,
  Tabs,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  InputAdornment
} from '@mui/material';
import { 
  Add as AddIcon, 
  MedicalServices as MedicalIcon,
  Vaccines as VaccineIcon,
  Pets as PetsIcon,
  Search as SearchIcon,
  FilterList as FilterIcon,
  CalendarMonth as CalendarIcon,
  Warning as WarningIcon
} from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { getMedicalActions, getUpcomingVaccinations, getAnimals } from '../api/api';
import format from 'date-fns/format';
import isBefore from 'date-fns/isBefore';
import addDays from 'date-fns/addDays';

// Composant TabPanel pour gérer les onglets
function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`medical-tabpanel-${index}`}
      aria-labelledby={`medical-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ pt: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

const MedicalActions = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [loading, setLoading] = useState(true);
  const [medicalActions, setMedicalActions] = useState([]);
  const [upcomingVaccinations, setUpcomingVaccinations] = useState([]);
  const [animals, setAnimals] = useState([]);
  const [tabValue, setTabValue] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [filter, setFilter] = useState({
    animalId: '',
    type: '',
    search: ''
  });

  // Récupérer les données au chargement
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        
        // Récupérer les actions médicales
        const medicalRes = await getMedicalActions();
        if (medicalRes.success) {
          setMedicalActions(medicalRes.data);
        }
        
        // Récupérer les vaccinations à venir
        const vaccinationsRes = await getUpcomingVaccinations();
        if (vaccinationsRes.success) {
          setUpcomingVaccinations(vaccinationsRes.data);
        }
        
        // Récupérer les animaux pour le filtre
        const animalsRes = await getAnimals();
        if (animalsRes && animalsRes.data) setAnimals(animalsRes.data);
      } catch (error) {
        console.error('Error fetching medical data:', error);
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, []);

  // Gérer le changement d'onglet
  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  // Gérer le changement de page
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  // Gérer le changement du nombre de lignes par page
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Gérer les changements de filtre
  const handleFilterChange = (event) => {
    const { name, value } = event.target;
    setFilter(prev => ({
      ...prev,
      [name]: value
    }));
    setPage(0);
  };

  // Filtrer les actions médicales
  const filteredMedicalActions = medicalActions.filter(action => {
    const actionAnimalId = action.animalId || action.animal?._id || action.animal?.id;
    // Filtre par animal
    if (filter.animalId && actionAnimalId !== filter.animalId) {
      return false;
    }
    
    // Filtre par type
    if (filter.type && action.type !== filter.type) {
      return false;
    }
    
    // Filtre par recherche
    if (filter.search) {
      const searchLower = filter.search.toLowerCase();
      return (
        action.animal?.name?.toLowerCase().includes(searchLower) ||
        action.name?.toLowerCase().includes(searchLower) ||
        action.notes?.toLowerCase().includes(searchLower) ||
        action.type?.toLowerCase().includes(searchLower)
      );
    }
    
    return true;
  });

  // Obtenir les actions médicales paginées
  const paginatedMedicalActions = filteredMedicalActions
    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);

  // Fonction pour déterminer la couleur du statut
  const getStatusColor = (date) => {
    if (!date) return theme.palette.info.main;
    
    const dueDate = new Date(date);
    const now = new Date();
    
    if (isBefore(dueDate, now)) {
      return theme.palette.error.main;
    }
    
    if (isBefore(dueDate, addDays(now, 30))) {
      return theme.palette.warning.main;
    }
    
    return theme.palette.success.main;
  };

  // Rendu des onglets
  const renderTabs = () => (
    <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
      <Tabs 
        value={tabValue} 
        onChange={handleTabChange}
        variant={isMobile ? "fullWidth" : "standard"}
        aria-label="medical actions tabs"
      >
        <Tab 
          icon={<MedicalIcon />} 
          iconPosition="start" 
          label="All Actions" 
          id="medical-tab-0" 
        />
        <Tab 
          icon={<VaccineIcon />} 
          iconPosition="start" 
          label="Upcoming Vaccinations" 
          id="medical-tab-1" 
        />
      </Tabs>
    </Box>
  );

  // Rendu des filtres
  const renderFilters = () => (
    <Box sx={{ mb: 3, mt: 2 }}>
      <Grid container spacing={2} alignItems="center">
        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth size="small" sx={{ minWidth: 180 }}>
            <InputLabel id="animal-filter-label">Animal</InputLabel>
            <Select
              labelId="animal-filter-label"
              id="animal-filter"
              name="animalId"
              value={filter.animalId}
              label="Animal"
              onChange={handleFilterChange}
            >
              <MenuItem value="">
                <em>All</em>
              </MenuItem>
              {animals.map(animal => (
                <MenuItem key={animal._id} value={animal._id}>
                  {animal.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>
        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth size="small" sx={{ minWidth: 180 }}>
            <InputLabel id="type-filter-label">Type</InputLabel>
            <Select
              labelId="type-filter-label"
              id="type-filter"
              name="type"
              value={filter.type}
              label="Type"
              onChange={handleFilterChange}
            >
              <MenuItem value="">
                <em>All</em>
              </MenuItem>
              <MenuItem value="vaccination">Vaccination</MenuItem>
              <MenuItem value="treatment">Treatment</MenuItem>
              <MenuItem value="checkup">Checkup</MenuItem>
              <MenuItem value="other">Other</MenuItem>
            </Select>
          </FormControl>
        </Grid>
        <Grid item xs={12} md={4}>
          <TextField
            fullWidth
            size="small"
            name="search"
            label="Search"
            value={filter.search}
            onChange={handleFilterChange}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
            }}
          />
        </Grid>
        <Grid item xs={12} md={12} sx={{ display: 'flex', justifyContent: { xs: 'flex-start', md: 'flex-end' } }}>
          <Button
            component={Link}
            to="/medical/new"
            variant="contained"
            startIcon={<AddIcon />}
            sx={{ ml: 'auto' }}
          >
            New Action
          </Button>
        </Grid>
      </Grid>
    </Box>
  );

  // Rendu du tableau des actions médicales
  const renderMedicalActionsTable = () => (
    <>
      <TableContainer component={Paper} elevation={2} sx={{ borderRadius: 2 }}>
        <Table size={isMobile ? "small" : "medium"}>
          <TableHead>
            <TableRow>
              <TableCell>Animal</TableCell>
              <TableCell>Type</TableCell>
              <TableCell>Action</TableCell>
              <TableCell>Date</TableCell>
              {!isMobile && <TableCell>Next Due Date</TableCell>}
              <TableCell>Status</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {paginatedMedicalActions.length > 0 ? (
              paginatedMedicalActions.map((action) => (
                (() => {
                  const actionAnimalId = action.animalId || action.animal?._id || action.animal?.id;
                  const animalName =
                    action.animal?.name ||
                    animals.find((a) => a._id === actionAnimalId)?.name ||
                    'Unknown';

                  return (
                <TableRow 
                  key={action._id} 
                  hover 
                  component={Link}
                  to={`/medical/${action._id}`}
                  sx={{ 
                    textDecoration: 'none',
                    '&:hover': {
                      backgroundColor: 'action.hover',
                    },
                  }}
                >
                  <TableCell>
                    <Box display="flex" alignItems="center">
                      <PetsIcon fontSize="small" sx={{ mr: 1, color: 'text.secondary' }} />
                      <Typography variant="body2">
                        {animalName}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={action.type === 'vaccination' ? 'Vaccination' : 
                             action.type === 'treatment' ? 'Treatment' : 
                             action.type === 'checkup' ? 'Checkup' : 'Other'} 
                      size="small" 
                      color={
                        action.type === 'vaccination' ? 'primary' : 
                        action.type === 'treatment' ? 'secondary' : 
                        action.type === 'checkup' ? 'info' : 'default'
                      }
                      sx={{ textTransform: 'capitalize' }}
                    />
                  </TableCell>
                  <TableCell>{action.name}</TableCell>
                  <TableCell>
                    {action.date ? format(new Date(action.date), 'dd/MM/yyyy') : 'N/A'}
                  </TableCell>
                  {!isMobile && (
                    <TableCell>
                      {action.nextDueDate ? format(new Date(action.nextDueDate), 'dd/MM/yyyy') : 'N/A'}
                    </TableCell>
                  )}
                  <TableCell>
                    <Chip 
                      icon={action.nextDueDate && isBefore(new Date(action.nextDueDate), new Date()) ? <WarningIcon /> : undefined}
                      label={action.nextDueDate ? 
                        isBefore(new Date(action.nextDueDate), new Date()) ? 
                          'Overdue' : 'Scheduled' : 'Completed'} 
                      size="small" 
                      sx={{ 
                        backgroundColor: action.nextDueDate ? 
                          `${getStatusColor(action.nextDueDate)}20` : `${theme.palette.success.main}20`,
                        color: action.nextDueDate ? 
                          getStatusColor(action.nextDueDate) : theme.palette.success.main,
                        fontWeight: 'medium'
                      }}
                    />
                  </TableCell>
                </TableRow>
                  );
                })()
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={isMobile ? 5 : 6} align="center">
                  <Typography variant="body2" color="textSecondary" sx={{ py: 2 }}>
                    No medical actions found
                  </Typography>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={filteredMedicalActions.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        labelRowsPerPage="Rows per page:"
        labelDisplayedRows={({ from, to, count }) => `${from}-${to} of ${count}`}
      />
    </>
  );

  // Rendu des vaccinations à venir
  const renderUpcomingVaccinations = () => (
    <Grid container spacing={3}>
      {upcomingVaccinations.length > 0 ? (
        upcomingVaccinations.map((vaccination) => (
          <Grid item xs={12} sm={6} md={4} lg={3} key={vaccination._id}>
            <Card
              elevation={2}
              sx={{
                height: '100%',
                borderLeft: `3px solid ${getStatusColor(vaccination.nextDueDate)}`,
                borderRadius: 2,
                overflow: 'hidden',
              }}
            >
              <CardActionArea
                component={Link}
                to={`/medical/${vaccination._id}`}
                sx={{ height: '100%', display: 'flex', alignItems: 'stretch' }}
              >
                <CardContent sx={{ p: 2, width: '100%' }}>
                  {(() => {
                    const vaccinationAnimalId = vaccination.animalId || vaccination.animal?._id || vaccination.animal?.id;
                    const animalName =
                      vaccination.animal?.name ||
                      animals.find((a) => a._id === vaccinationAnimalId)?.name ||
                      'Unknown';

                    const statusLabel = isBefore(new Date(vaccination.nextDueDate), new Date())
                      ? 'Overdue'
                      : isBefore(new Date(vaccination.nextDueDate), addDays(new Date(), 30))
                        ? 'Due soon'
                        : 'Scheduled';

                    return (
                      <>
                        <Box display="flex" justifyContent="space-between" alignItems="flex-start" gap={1}>
                          <Box sx={{ minWidth: 0 }}>
                            <Typography variant="subtitle1" fontWeight="medium" noWrap>
                              {animalName}
                            </Typography>
                            <Typography variant="body2" color="text.secondary" noWrap>
                              {vaccination.name}
                            </Typography>
                          </Box>
                          <Chip
                            label={statusLabel}
                            size="small"
                            sx={{
                              backgroundColor: `${getStatusColor(vaccination.nextDueDate)}20`,
                              color: getStatusColor(vaccination.nextDueDate),
                              fontWeight: 'medium',
                              mt: 0.25,
                            }}
                          />
                        </Box>

                        <Divider sx={{ my: 1.5 }} />

                        <Grid container spacing={1}>
                          <Grid item xs={6}>
                            <Typography variant="caption" color="text.secondary">
                              Last date
                            </Typography>
                            <Typography variant="body2">
                              {vaccination.date ? format(new Date(vaccination.date), 'dd/MM/yyyy') : 'N/A'}
                            </Typography>
                          </Grid>
                          <Grid item xs={6}>
                            <Typography variant="caption" color="text.secondary">
                              Next date
                            </Typography>
                            <Typography variant="body2" fontWeight="medium" color={getStatusColor(vaccination.nextDueDate)}>
                              {vaccination.nextDueDate ? format(new Date(vaccination.nextDueDate), 'dd/MM/yyyy') : 'N/A'}
                            </Typography>
                          </Grid>
                        </Grid>
                      </>
                    );
                  })()}
                </CardContent>
              </CardActionArea>
            </Card>
          </Grid>
        ))
      ) : (
        <Grid item xs={12}>
          <Alert severity="info">
            No upcoming vaccinations found.
          </Alert>
        </Grid>
      )}
    </Grid>
  );

  return (
    <Box>
      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Typography variant="h5" gutterBottom>
          Medical Actions
        </Typography>
      </Box>

      {renderTabs()}
      
      {loading ? (
        <Box display="flex" justifyContent="center" p={3}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <TabPanel value={tabValue} index={0}>
            {renderFilters()}
            {renderMedicalActionsTable()}
          </TabPanel>
          <TabPanel value={tabValue} index={1}>
            {renderUpcomingVaccinations()}
          </TabPanel>
        </>
      )}
    </Box>
  );
};

export default MedicalActions;
