// Import des services Firebase
import * as animalService from '../firebase/animalService';
import * as feedingService from '../firebase/feedingService';
import * as medicalService from '../firebase/medicalService';

// API pour les animaux
export const getAnimals = () => {
  return animalService.getAllAnimals();
};

export const getAnimalById = (id) => {
  return animalService.getAnimalById(id);
};

export const createAnimal = (animalData) => {
  return animalService.createAnimal(animalData);
};

export const updateAnimal = (id, animalData) => {
  return animalService.updateAnimal(id, animalData);
};

export const deleteAnimal = (id) => {
  return animalService.deleteAnimal(id);
};

// API pour les enregistrements d'alimentation
export const getFeedings = (params) => {
  return feedingService.getAllFeedings(params);
};

export const getFeedingById = (id) => {
  return feedingService.getFeedingById(id);
};

export const createFeeding = (feedingData) => {
  return feedingService.createFeeding(feedingData);
};

export const updateFeeding = (id, feedingData) => {
  return feedingService.updateFeeding(id, feedingData);
};

export const deleteFeeding = (id) => {
  return feedingService.deleteFeeding(id);
};

export const getTodayFeedings = () => {
  return feedingService.getTodayFeedings();
};

// API pour les actions médicales
export const getMedicalActions = (params) => {
  return medicalService.getAllMedicalActions(params);
};

export const getMedicalActionById = (id) => {
  return medicalService.getMedicalActionById(id);
};

export const createMedicalAction = (medicalData) => {
  return medicalService.createMedicalAction(medicalData);
};

export const updateMedicalAction = (id, medicalData) => {
  return medicalService.updateMedicalAction(id, medicalData);
};

export const deleteMedicalAction = (id) => {
  return medicalService.deleteMedicalAction(id);
};

export const getUpcomingVaccinations = () => {
  return medicalService.getUpcomingVaccinations();
};

export default {
  getAnimals,
  getAnimalById,
  createAnimal,
  updateAnimal,
  deleteAnimal,
  getFeedings,
  getFeedingById,
  createFeeding,
  updateFeeding,
  deleteFeeding,
  getTodayFeedings,
  getMedicalActions,
  getMedicalActionById,
  createMedicalAction,
  updateMedicalAction,
  deleteMedicalAction,
  getUpcomingVaccinations
};
