import { db } from './config';
import { collection, getDocs, setDoc, doc } from 'firebase/firestore';

// Fonction pour vérifier si une collection existe et la créer si nécessaire
export const initializeFirestore = async () => {
  try {
    // Vérifier si la collection 'animals' existe
    const animalsRef = collection(db, 'animals');
    const animalsSnapshot = await getDocs(animalsRef);
    
    // Si la collection est vide, ajouter un document exemple
    if (animalsSnapshot.empty) {
      console.log('Initializing animals collection...');
      await setDoc(doc(db, 'animals', 'example'), {
        name: 'Example Animal',
        species: 'Example Species',
        enclosure: 'Example Enclosure',
        status: 'active',
        notes: 'This is an example animal',
        createdAt: new Date(),
        updatedAt: new Date()
      });
    }

    // Vérifier si la collection 'feedings' existe
    const feedingsRef = collection(db, 'feedings');
    const feedingsSnapshot = await getDocs(feedingsRef);
    
    // Si la collection est vide, ajouter un document exemple
    if (feedingsSnapshot.empty) {
      console.log('Initializing feedings collection...');
      await setDoc(doc(db, 'feedings', 'example'), {
        animalId: 'example',
        date: new Date(),
        status: 'completed',
        notes: 'This is an example feeding',
        createdAt: new Date(),
        updatedAt: new Date()
      });
    }

    console.log('Firebase collections initialized successfully!');
    return true;
  } catch (error) {
    console.error('Error initializing Firebase collections:', error);
    return false;
  }
};

export default initializeFirestore;
