import React, { useState } from 'react';
import { 
  Button, 
  Dialog, 
  DialogActions, 
  DialogContent, 
  DialogContentText, 
  DialogTitle,
  CircularProgress,
  Alert,
  Box,
  Typography
} from '@mui/material';
import { Refresh as RefreshIcon } from '@mui/icons-material';
import { db } from '../../firebase/config';
import { collection, getDocs, deleteDoc, doc, updateDoc, Timestamp } from 'firebase/firestore';
import { checkAndResetFeedings } from '../../utils/resetService';

const FEEDINGS_COLLECTION = 'feedings';
const ANIMALS_COLLECTION = 'animals';

const NewDayButton = () => {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(null);
  const [result, setResult] = useState({ feedingsReset: 0, notesReset: 0 });

  const handleClickOpen = () => {
    setOpen(true);
    setSuccess(false);
    setError(null);
    setResult({ feedingsReset: 0, notesReset: 0 });
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleNewDay = async () => {
    setLoading(true);
    setSuccess(false);
    setError(null);
    
    try {
      // Utiliser la fonction existante pour réinitialiser les feedings et les notes
      const result = await checkAndResetFeedings(true);
      
      // Mettre à jour la date de dernière réinitialisation
      localStorage.setItem('lastFeedingReset', new Date().toISOString());
      
      setResult(result);
      setSuccess(true);
      console.log(`Nouvelle journée initialisée : ${result.feedingsReset} feedings supprimés, ${result.notesReset} notes d'animaux réinitialisées`);
    } catch (error) {
      console.error('Erreur lors de l\'initialisation de la nouvelle journée:', error);
      setError(error.message || 'Une erreur est survenue');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Button
        variant="contained"
        color="primary"
        startIcon={<RefreshIcon />}
        onClick={handleClickOpen}
        fullWidth
      >
        Start New Day
      </Button>
      
      <Dialog open={open} onClose={loading ? null : handleClose}>
        <DialogTitle>Start New Day</DialogTitle>
        <DialogContent>
          <DialogContentText>
            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
              This will prepare the system for a new day by:
            </Typography>
            <Typography variant="body2" component="div">
              <ul>
                <li>Deleting all previous feeding records</li>
                <li>Resetting daily notes for all animals</li>
                <li>Clearing last feeding timestamps</li>
              </ul>
            </Typography>
            <Typography variant="body2" paragraph color="error">
              This action cannot be undone. All previous feeding data will be permanently lost.
            </Typography>
            <Typography variant="body2">
              Are you sure you want to start a new day?
            </Typography>
          </DialogContentText>
          
          {loading && (
            <Box display="flex" justifyContent="center" my={2}>
              <CircularProgress />
            </Box>
          )}
          
          {success && (
            <Alert severity="success" sx={{ mt: 2 }}>
              New day started successfully! {result.feedingsReset} feeding records deleted and {result.notesReset} animal notes reset.
            </Alert>
          )}
          
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose} color="inherit" disabled={loading}>
            Cancel
          </Button>
          <Button 
            onClick={handleNewDay} 
            color="primary" 
            disabled={loading}
            variant="contained"
          >
            {loading ? 'Processing...' : 'Start New Day'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default NewDayButton;
