import { db } from './config';
import { 
  collection, 
  doc, 
  getDocs, 
  getDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy, 
  serverTimestamp 
} from 'firebase/firestore';

import { getAnimalById } from './animalService';

const COLLECTION_NAME = 'medicalActions';

const toIsoIfTimestamp = (value) => {
  if (value && typeof value === 'object' && typeof value.toDate === 'function') {
    return value.toDate().toISOString();
  }
  return value;
};

const getAnimalIdFromAction = (action) => {
  const candidate = action?.animalId || action?.animal?._id || action?.animal?.id;
  return candidate ? String(candidate) : null;
};

// Récupérer toutes les actions médicales
export const getAllMedicalActions = async (params = {}) => {
  try {
    const medicalRef = collection(db, COLLECTION_NAME);

    // Construire la requête (même stratégie que feedingService pour éviter les index manquants)
    const conditions = [];

    if (params.animalId) {
      const animalId = typeof params.animalId === 'object' && params.animalId._id ?
        params.animalId._id : params.animalId;
      conditions.push(where('animalId', '==', String(animalId)));
      // Ne pas ajouter orderBy ici pour éviter l'erreur d'index manquant.
      // Tri côté client plus bas.
    } else {
      conditions.push(orderBy('date', 'desc'));
    }

    const medicalQuery = query(medicalRef, ...conditions);
    const snapshot = await getDocs(medicalQuery);

    const medicalActionsRaw = snapshot.docs.map(d => ({
      _id: d.id,
      ...d.data(),
    }));

    const medicalActions = await Promise.all(
      medicalActionsRaw.map(async (action) => {
        const normalized = {
          ...action,
          animalId: getAnimalIdFromAction(action),
          date: toIsoIfTimestamp(action.date) || toIsoIfTimestamp(action.createdAt) || null,
          nextDueDate: toIsoIfTimestamp(action.nextDueDate),
          createdAt: toIsoIfTimestamp(action.createdAt),
          updatedAt: toIsoIfTimestamp(action.updatedAt),
        };

        if (normalized.animalId) {
          try {
            const animalRes = await getAnimalById(normalized.animalId);
            normalized.animal = animalRes?.data || null;
          } catch {
            normalized.animal = null;
          }
        }

        return normalized;
      })
    );

    // Tri côté client si on filtre par animalId
    if (params.animalId) {
      medicalActions.sort((a, b) => {
        const dateA = a.date ? new Date(a.date) : new Date(0);
        const dateB = b.date ? new Date(b.date) : new Date(0);
        return dateB - dateA;
      });
    }

    return { success: true, data: medicalActions };
  } catch (error) {
    console.error('Error getting medical actions:', error);
    return { success: false, error: error.message };
  }
};

// Récupérer une action médicale par ID
export const getMedicalActionById = async (id) => {
  try {
    const docRef = doc(db, COLLECTION_NAME, id);
    const docSnap = await getDoc(docRef);
    
    if (docSnap.exists()) {
      const raw = { _id: docSnap.id, ...docSnap.data() };
      const data = {
        ...raw,
        date: toIsoIfTimestamp(raw.date) || toIsoIfTimestamp(raw.createdAt) || null,
        nextDueDate: toIsoIfTimestamp(raw.nextDueDate),
        createdAt: toIsoIfTimestamp(raw.createdAt),
        updatedAt: toIsoIfTimestamp(raw.updatedAt),
      };

      if (data.animalId) {
        try {
          const animalRes = await getAnimalById(data.animalId);
          data.animal = animalRes?.data || null;
        } catch {
          data.animal = null;
        }
      }

      return { success: true, data };
    } else {
      return { 
        success: false, 
        error: 'Medical action not found' 
      };
    }
  } catch (error) {
    console.error('Error getting medical action:', error);
    return { success: false, error: error.message };
  }
};

// Créer une nouvelle action médicale
export const createMedicalAction = async (medicalData) => {
  try {
    const normalizedAnimalId = getAnimalIdFromAction(medicalData);
    const docRef = await addDoc(collection(db, COLLECTION_NAME), {
      ...medicalData,
      ...(normalizedAnimalId ? { animalId: normalizedAnimalId } : {}),
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp()
    });
    
    return { 
      success: true, 
      data: { _id: docRef.id, ...medicalData } 
    };
  } catch (error) {
    console.error('Error creating medical action:', error);
    return { success: false, error: error.message };
  }
};

// Mettre à jour une action médicale
export const updateMedicalAction = async (id, medicalData) => {
  try {
    const docRef = doc(db, COLLECTION_NAME, id);
    const normalizedAnimalId = getAnimalIdFromAction(medicalData);
    await updateDoc(docRef, {
      ...medicalData,
      ...(normalizedAnimalId ? { animalId: normalizedAnimalId } : {}),
      updatedAt: serverTimestamp()
    });
    
    return { 
      success: true, 
      data: { _id: id, ...medicalData } 
    };
  } catch (error) {
    console.error('Error updating medical action:', error);
    return { success: false, error: error.message };
  }
};

// Supprimer une action médicale
export const deleteMedicalAction = async (id) => {
  try {
    const docRef = doc(db, COLLECTION_NAME, id);
    await deleteDoc(docRef);
    
    return { success: true };
  } catch (error) {
    console.error('Error deleting medical action:', error);
    return { success: false, error: error.message };
  }
};

// Récupérer les actions médicales à venir (vaccins prévus)
export const getUpcomingVaccinations = async () => {
  try {
    const now = new Date();
    
    // Approche alternative pour éviter l'erreur d'index
    // 1. D'abord, récupérer toutes les actions de type vaccination
    const vaccinationsQuery = query(
      collection(db, COLLECTION_NAME),
      where('type', '==', 'vaccination')
    );
    
    const snapshot = await getDocs(vaccinationsQuery);
    
    // 2. Filtrer côté client pour les vaccinations à venir
    const upcomingVaccinations = snapshot.docs
      .map(doc => ({
        _id: doc.id,
        ...doc.data()
      }))
      .filter(vaccination => {
        // Vérifier si nextDueDate existe et est supérieure ou égale à maintenant
        if (!vaccination.nextDueDate) return false;
        
        const nextDueDate = new Date(toIsoIfTimestamp(vaccination.nextDueDate));
        return nextDueDate >= now;
      })
      // Trier par date croissante
      .sort((a, b) => {
        const dateA = new Date(toIsoIfTimestamp(a.nextDueDate));
        const dateB = new Date(toIsoIfTimestamp(b.nextDueDate));
        return dateA - dateB; // Tri croissant (plus proche au plus éloigné)
      });

    const hydrated = await Promise.all(
      upcomingVaccinations.map(async (action) => {
        const normalized = {
          ...action,
          animalId: getAnimalIdFromAction(action),
          date: toIsoIfTimestamp(action.date),
          nextDueDate: toIsoIfTimestamp(action.nextDueDate),
        };

        if (normalized.animalId) {
          try {
            const animalRes = await getAnimalById(normalized.animalId);
            normalized.animal = animalRes?.data || null;
          } catch {
            normalized.animal = null;
          }
        }

        return normalized;
      })
    );
    
    return { success: true, data: hydrated };
  } catch (error) {
    console.error('Error getting upcoming vaccinations:', error);
    return { success: false, error: error.message };
  }
};
