import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Button, 
  Typography, 
  Paper, 
  Grid,
  TextField,
  InputAdornment,
  CircularProgress,
  useTheme,
  useMediaQuery,
  Pagination,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Tooltip,
  Badge,
  Chip
} from '@mui/material';
import { 
  Add as AddIcon, 
  Search as SearchIcon,
  Pets as PetsIcon,
  Delete as DeleteIcon,
  RestaurantMenu as RestaurantMenuIcon,
  NotificationsActive as NotificationsActiveIcon
} from '@mui/icons-material';
import AnimalCard from '../components/animals/AnimalCard';
import { Link, useNavigate } from 'react-router-dom';
import { getAnimals, deleteAnimal, getTodayFeedings } from '../api/api';
import ConfirmationDialog from '../components/common/ConfirmationDialog';

export default function Animals() {
  const [animals, setAnimals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(50);
  const [searchTerm, setSearchTerm] = useState('');
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedAnimal, setSelectedAnimal] = useState(null);
  const [todayFeedings, setTodayFeedings] = useState([]);
  const [showUnfedOnly, setShowUnfedOnly] = useState(false);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();

  useEffect(() => {
    fetchAnimals();
    fetchTodayFeedings();
  }, []);

  const fetchAnimals = async () => {
    try {
      setLoading(true);
      const response = await getAnimals();
      setAnimals(response.data || []);
    } catch (error) {
      console.error('Error fetching animals:', error);
    } finally {
      setLoading(false);
    }
  };
  
  const fetchTodayFeedings = async () => {
    try {
      const response = await getTodayFeedings();
      if (response.success && response.data) {
        setTodayFeedings(response.data);
      } else {
        setTodayFeedings([]);
      }
    } catch (error) {
      console.error('Error fetching today\'s feedings:', error);
      setTodayFeedings([]);
    }
  };
  
  // Vérifie si un animal a été nourri aujourd'hui
  const isAnimalFedToday = (animalId) => {
    return todayFeedings.some(feeding => feeding.animalId === animalId);
  };

  const handleDeleteClick = (animal) => {
    setSelectedAnimal(animal);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!selectedAnimal) return;
    
    try {
      await deleteAnimal(selectedAnimal._id);
      setAnimals(animals.filter(animal => animal._id !== selectedAnimal._id));
    } catch (error) {
      console.error('Error deleting animal:', error);
    } finally {
      setDeleteDialogOpen(false);
      setSelectedAnimal(null);
    }
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };
  console.log(rowsPerPage);
  // Filtrer les animaux en fonction du terme de recherche et du filtre "non nourris"
  const filteredAnimals = animals
    .filter(animal => {
      // Filtrer par terme de recherche
      const matchesSearch = animal.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          animal.species.toLowerCase().includes(searchTerm.toLowerCase());
      
      // Filtrer par statut d'alimentation si le filtre est activé
      const matchesFeedingStatus = showUnfedOnly ? !isAnimalFedToday(animal._id) : true;
      
      return matchesSearch && matchesFeedingStatus;
    })
    .sort((a, b) => a.name.localeCompare(b.name)); // Tri alphabétique par nom

  const emptyRows = 
    page > 0 ? Math.max(0, (1 + page) * rowsPerPage - filteredAnimals.length) : 0;

  return (
    <Box>
      <Box 
        display="flex" 
        justifyContent="space-between" 
        alignItems="center" 
        mb={3}
        flexDirection={isMobile ? 'column' : 'row'}
        gap={2}
      >
        <Typography variant="h5" component="h1">
          Animals
        </Typography>
        <Box display="flex" gap={2} width={isMobile ? '100%' : 'auto'}>
          <Box display="flex" gap={2} flexDirection={isMobile ? 'column' : 'row'} width="100%">
            <TextField
              size="small"
              placeholder="Search animals..."
              variant="outlined"
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                setPage(0);
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
              fullWidth
            />
            <Button
              variant={showUnfedOnly ? "contained" : "outlined"}
              color="warning"
              startIcon={<RestaurantMenuIcon />}
              onClick={() => setShowUnfedOnly(!showUnfedOnly)}
              sx={{ whiteSpace: 'nowrap' }}
            >
              {showUnfedOnly ? "Show All" : "Show Unfed Only"}
            </Button>
          </Box>
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddIcon />}
            component={Link}
            to="/animals/new"
            sx={{ whiteSpace: 'nowrap' }}
          >
            Add Animal
          </Button>
        </Box>
      </Box>

      <Paper elevation={2} sx={{ borderRadius: 2, overflow: 'hidden' }}>
        {loading ? (
          <Box display="flex" justifyContent="center" p={4}>
            <CircularProgress />
          </Box>
        ) : filteredAnimals.length === 0 ? (
          <Box textAlign="center" p={4}>
            <PetsIcon color="disabled" sx={{ fontSize: 48, mb: 2 }} />
            <Typography variant="subtitle1" color="textSecondary">
              {searchTerm ? 'No animals match your search' : 'No animals found'}
            </Typography>
            {!searchTerm && (
              <Button
                variant="outlined"
                color="primary"
                startIcon={<AddIcon />}
                component={Link}
                to="/animals/new"
                sx={{ mt: 2 }}
              >
                Add Your First Animal
              </Button>
            )}
          </Box>
        ) : (
          <>
            <Grid container spacing={3} sx={{ mb: 4, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              {(rowsPerPage > 0
                ? filteredAnimals.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                : filteredAnimals
              ).map((animal) => (
                <Grid item xs={4} sm={6} md={4} lg={3}key={animal._id}>
                  <Box sx={{ position: 'relative' }}>
                    {!isAnimalFedToday(animal._id) && (
                      <Chip
                        icon={<NotificationsActiveIcon />}
                        label="Unfed"
                        color="warning"
                        size="small"
                        width="100em !important"
                        sx={{
                          position: 'absolute',
                          top: 8,
                          right: 8,
                          zIndex: 10,
                        }}
                      />
                    )}
                    <AnimalCard animal={animal} />
                    <Tooltip title="Delete">
                      <IconButton
                        size="small"
                        color="error"
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          handleDeleteClick(animal);
                        }}
                        sx={{
                          position: 'absolute',
                          top: 8,
                          left: 8,
                          bgcolor: 'rgba(255, 255, 255, 0.8)',
                          '&:hover': {
                            bgcolor: 'rgba(255, 255, 255, 0.9)',
                          }
                        }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                </Grid>
              ))}
            </Grid>
            
            <Box display="flex" justifyContent="center" mt={4}>
              <Pagination
                count={Math.ceil(filteredAnimals.length / rowsPerPage)}
                page={page + 1}
                onChange={(event, newPage) => handleChangePage(event, newPage - 1)}
                color="primary"
              />
            </Box>
          </>
        )}
      </Paper>

      <ConfirmationDialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Delete Animal"
        content={`Are you sure you want to delete ${selectedAnimal?.name}? This action cannot be undone.`}
        confirmText="Delete"
        confirmColor="error"
      />
    </Box>
  );
}
