import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useDrawer } from '../../contexts/DrawerContext';
import {
  Drawer,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  Toolbar,
  Box,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import {
  Dashboard as DashboardIcon,
  Pets as AnimalsIcon,
  Pets as PetsIcon,
  Restaurant as FeedingIcon,
  Restaurant as RestaurantIcon,
  Home as HomeIcon,
  Settings as SettingsIcon,
  MedicalServices as MedicalIcon,
  Vaccines as VaccineIcon,
} from '@mui/icons-material';

const drawerWidth = 240;

const menuItems = [
  { text: 'Dashboard', icon: <HomeIcon />, path: '/' },
  { text: 'Animals', icon: <PetsIcon />, path: '/animals' },
  { text: 'Feedings', icon: <RestaurantIcon />, path: '/feedings' },
  { text: 'Medical', icon: <VaccineIcon />, path: '/medical' },
  { text: 'Settings', icon: <SettingsIcon />, path: '/settings' },
];

const Sidebar = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { mobileOpen, handleDrawerToggle, closeDrawer } = useDrawer();

  const drawer = (
    <div>
      <Toolbar>
        <Box sx={{ display: 'flex', alignItems: 'center', p: 2 }}>
          <DashboardIcon color="primary" sx={{ mr: 1 }} />
          <Typography variant="h6" noWrap component="div">
            Zoo Admin
          </Typography>
        </Box>
      </Toolbar>
      <Divider />
      <List sx={{ px: 1 }}>
        {menuItems.map((item) => (
          <ListItem
            button
            key={item.text}
            onClick={() => {
              navigate(item.path);
              // Fermer le drawer mobile lors d'un changement de page
              closeDrawer();
            }}
            selected={location.pathname === item.path}
            sx={{
              '&.Mui-selected': {
                backgroundColor: (theme) => alpha(theme.palette.primary.main, 0.12),
                '&:hover': {
                  backgroundColor: (theme) => alpha(theme.palette.primary.main, 0.18),
                },
              },
              '&:hover': {
                backgroundColor: (theme) => alpha(theme.palette.text.primary, 0.04),
              },
              borderRadius: 1,
              px: 2,
              my: 0.5,
            }}
          >
            <ListItemIcon sx={{ color: location.pathname === item.path ? 'primary.main' : 'inherit' }}>
              {item.icon}
            </ListItemIcon>
            <ListItemText primary={item.text} />
          </ListItem>
        ))}
      </List>
    </div>
  );

  return (
    <Box
      component="nav"
      sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}
      aria-label="mailbox folders"
    >
      {/* Mobile drawer */}
      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={handleDrawerToggle}
        ModalProps={{
          keepMounted: true, // Better open performance on mobile.
        }}
        sx={{
          display: { xs: 'block', sm: 'none' },
          '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth, overflowX: 'hidden' },
        }}
      >
        {drawer}
      </Drawer>
      
      {/* Desktop drawer */}
      <Drawer
        variant="permanent"
        sx={{
          display: { xs: 'none', sm: 'block' },
          '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth, overflowX: 'hidden' },
        }}
        open
      >
        {drawer}
      </Drawer>
    </Box>
  );
};

export default Sidebar;
