import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Typography, 
  Paper, 
  Grid, 
  Button, 
  Divider, 
  Chip, 
  CircularProgress,
  IconButton,
  Card,
  CardContent,
  useTheme,
  useMediaQuery,
  Alert
} from '@mui/material';
import { 
  ArrowBack as ArrowBackIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  MedicalServices as MedicalIcon,
  CalendarMonth as CalendarIcon,
  Pets as PetsIcon,
  Vaccines as VaccineIcon,
  Warning as WarningIcon
} from '@mui/icons-material';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { getMedicalActionById, deleteMedicalAction } from '../api/api';
import format from 'date-fns/format';
import isBefore from 'date-fns/isBefore';
import addDays from 'date-fns/addDays';
import ConfirmationDialog from '../components/common/ConfirmationDialog';

const MedicalDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [loading, setLoading] = useState(true);
  const [medicalAction, setMedicalAction] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [error, setError] = useState(null);

  // Récupérer les données de l'action médicale
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const response = await getMedicalActionById(id);
        
        if (response.success) {
          setMedicalAction(response.data);
        } else {
          setError('Medical action not found');
        }
      } catch (error) {
        console.error('Error fetching medical action:', error);
        setError('Error loading data');
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, [id]);

  // Gérer la suppression
  const handleDelete = () => {
    setDeleteDialogOpen(true);
  };

  // Confirmer la suppression
  const confirmDelete = async () => {
    try {
      setLoading(true);
      const response = await deleteMedicalAction(id);
      
      if (response.success) {
        navigate('/medical');
      } else {
        setError('Error deleting medical action');
      }
    } catch (error) {
      console.error('Error deleting medical action:', error);
      setError('Error deleting medical action');
    } finally {
      setLoading(false);
      setDeleteDialogOpen(false);
    }
  };

  // Fonction pour déterminer la couleur du statut
  const getStatusColor = (date) => {
    if (!date) return theme.palette.info.main;
    
    const dueDate = new Date(date);
    const now = new Date();
    
    if (isBefore(dueDate, now)) {
      return theme.palette.error.main;
    }
    
    if (isBefore(dueDate, addDays(now, 30))) {
      return theme.palette.warning.main;
    }
    
    return theme.palette.success.main;
  };

  // Fonction pour obtenir le libellé du type
  const getTypeLabel = (type) => {
    switch (type) {
      case 'vaccination':
        return 'Vaccination';
      case 'treatment':
        return 'Treatment';
      case 'checkup':
        return 'Checkup';
      default:
        return 'Other';
    }
  };

  // Fonction pour obtenir la couleur du type
  const getTypeColor = (type) => {
    switch (type) {
      case 'vaccination':
        return 'primary';
      case 'treatment':
        return 'secondary';
      case 'checkup':
        return 'info';
      default:
        return 'default';
    }
  };

  // Fonction pour obtenir l'icône du type
  const getTypeIcon = (type) => {
    switch (type) {
      case 'vaccination':
        return <VaccineIcon fontSize="small" />;
      case 'treatment':
        return <MedicalIcon fontSize="small" />;
      case 'checkup':
        return <MedicalIcon fontSize="small" />;
      default:
        return <MedicalIcon fontSize="small" />;
    }
  };

  // Rendu du contenu principal
  const renderContent = () => {
    if (!medicalAction) return null;

    const animalName = medicalAction.animal?.name || 'Unknown';
    const dateTextShort = medicalAction.date ? format(new Date(medicalAction.date), 'dd/MM/yyyy') : 'N/A';
    const dateTextLong = medicalAction.date ? format(new Date(medicalAction.date), 'dd MMMM yyyy') : 'N/A';

    return (
      <Grid container spacing={3}>
        {/* En-tête avec informations principales */}
        <Grid item xs={12}>
          <Paper elevation={2} sx={{ p: 3, borderRadius: 2 }}>
            <Box sx={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', justifyContent: 'space-between', alignItems: isMobile ? 'flex-start' : 'center', mb: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: isMobile ? 2 : 0 }}>
                <Box
                  sx={{
                    backgroundColor: `${theme.palette[getTypeColor(medicalAction.type)].main}20`,
                    borderRadius: '50%',
                    width: 48,
                    height: 48,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    mr: 2,
                  }}
                >
                  {getTypeIcon(medicalAction.type)}
                </Box>
                <Box>
                  <Typography variant="h5" component="h1">
                    {medicalAction.name}
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', mt: 0.5 }}>
                    <Chip 
                      icon={getTypeIcon(medicalAction.type)}
                      label={getTypeLabel(medicalAction.type)} 
                      size="small" 
                      color={getTypeColor(medicalAction.type)}
                      sx={{ mr: 1 }}
                    />
                    <Typography variant="body2" color="textSecondary">
                      {dateTextShort}
                    </Typography>
                  </Box>
                </Box>
              </Box>
              <Box>
                <Button
                  component={Link}
                  to={`/medical/${id}/edit`}
                  variant="outlined"
                  startIcon={<EditIcon />}
                  sx={{ mr: 1 }}
                >
                  Edit
                </Button>
                <Button
                  variant="outlined"
                  color="error"
                  startIcon={<DeleteIcon />}
                  onClick={handleDelete}
                >
                  Delete
                </Button>
              </Box>
            </Box>
            
            <Divider sx={{ my: 2 }} />
            
            <Grid container spacing={3}>
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  Animal
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <PetsIcon sx={{ mr: 1, color: theme.palette.primary.main }} />
                  <Typography variant="body1">
                    {animalName}
                  </Typography>
                </Box>
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  Action date
                </Typography>
                <Typography variant="body1">
                  {dateTextLong}
                </Typography>
              </Grid>
              
              {medicalAction.nextDueDate && (
                <Grid item xs={12} sm={6}>
                  <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                    Next due date
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center' }}>
                    <CalendarIcon sx={{ mr: 1, color: getStatusColor(medicalAction.nextDueDate) }} />
                    <Typography 
                      variant="body1" 
                      sx={{ color: getStatusColor(medicalAction.nextDueDate) }}
                    >
                      {format(new Date(medicalAction.nextDueDate), 'dd MMMM yyyy')}
                    </Typography>
                  </Box>
                </Grid>
              )}
              
              {medicalAction.frequency && (
                <Grid item xs={12} sm={6}>
                  <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                    Frequency
                  </Typography>
                  <Typography variant="body1">
                    {medicalAction.frequency === 1 
                      ? 'Every month' 
                      : `Every ${medicalAction.frequency} months`}
                  </Typography>
                </Grid>
              )}
            </Grid>
          </Paper>
        </Grid>
        
        {/* Statut et alerte */}
        {medicalAction.nextDueDate && (
          <Grid item xs={12}>
            <Paper 
              elevation={2} 
              sx={{ 
                p: 3, 
                borderRadius: 2,
                borderLeft: `4px solid ${getStatusColor(medicalAction.nextDueDate)}`
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                {isBefore(new Date(medicalAction.nextDueDate), new Date()) && (
                  <WarningIcon sx={{ mr: 1, color: theme.palette.error.main }} />
                )}
                <Typography variant="h6" color={getStatusColor(medicalAction.nextDueDate)}>
                  {isBefore(new Date(medicalAction.nextDueDate), new Date())
                    ? 'Medical action overdue'
                    : isBefore(new Date(medicalAction.nextDueDate), addDays(new Date(), 30))
                    ? 'Medical action due soon'
                    : 'Medical action scheduled'}
                </Typography>
              </Box>
              <Typography variant="body1" sx={{ mt: 1 }}>
                {isBefore(new Date(medicalAction.nextDueDate), new Date())
                  ? `This medical action should have been completed on ${format(new Date(medicalAction.nextDueDate), 'dd/MM/yyyy')}.`
                  : isBefore(new Date(medicalAction.nextDueDate), addDays(new Date(), 30))
                  ? `This medical action is due on ${format(new Date(medicalAction.nextDueDate), 'dd/MM/yyyy')}.`
                  : `This medical action is scheduled for ${format(new Date(medicalAction.nextDueDate), 'dd/MM/yyyy')}.`}
              </Typography>
            </Paper>
          </Grid>
        )}
        
        {/* Notes */}
        <Grid item xs={12}>
          <Paper elevation={2} sx={{ p: 3, borderRadius: 2 }}>
            <Typography variant="h6" gutterBottom>
              Notes
            </Typography>
            <Divider sx={{ mb: 2 }} />
            <Typography variant="body1">
              {medicalAction.notes || 'No notes.'}
            </Typography>
          </Paper>
        </Grid>
      </Grid>
    );
  };

  return (
    <Box>
      <Box sx={{ mb: 3, display: 'flex', alignItems: 'center' }}>
        <IconButton 
          component={Link} 
          to="/medical"
          sx={{ mr: 1 }}
        >
          <ArrowBackIcon />
        </IconButton>
        <Typography variant="h5">
          Medical action details
        </Typography>
      </Box>

      {loading ? (
        <Box display="flex" justifyContent="center" p={3}>
          <CircularProgress />
        </Box>
      ) : error ? (
        <Alert severity="error">{error}</Alert>
      ) : (
        renderContent()
      )}

      {/* Dialogue de confirmation de suppression */}
      <ConfirmationDialog
        open={deleteDialogOpen}
        title="Delete medical action"
        content="Are you sure you want to delete this medical action? This action cannot be undone."
        onConfirm={confirmDelete}
        onClose={() => setDeleteDialogOpen(false)}
      />
    </Box>
  );
};

export default MedicalDetail;
