import { db } from '../firebase/config';
import { collection, getDocs, deleteDoc, doc, writeBatch } from 'firebase/firestore';

// Fonction pour supprimer tous les documents d'une collection
const deleteCollection = async (collectionName) => {
  try {
    console.log(`Starting deletion of ${collectionName} collection...`);
    const collectionRef = collection(db, collectionName);
    const snapshot = await getDocs(collectionRef);
    
    if (snapshot.empty) {
      console.log(`No documents found in ${collectionName} collection.`);
      return { count: 0, success: true };
    }
    
    // Utiliser un batch pour supprimer plusieurs documents à la fois
    const batchSize = 500; // Firestore limite à 500 opérations par batch
    let count = 0;
    let batch = writeBatch(db);
    let batchCount = 0;
    
    for (const document of snapshot.docs) {
      batch.delete(doc(db, collectionName, document.id));
      batchCount++;
      count++;
      
      // Si nous atteignons la limite du batch, commettre et créer un nouveau batch
      if (batchCount >= batchSize) {
        await batch.commit();
        console.log(`Committed batch of ${batchCount} deletions.`);
        batch = writeBatch(db);
        batchCount = 0;
      }
    }
    
    // Commettre le dernier batch s'il reste des documents
    if (batchCount > 0) {
      await batch.commit();
      console.log(`Committed final batch of ${batchCount} deletions.`);
    }
    
    console.log(`Successfully deleted ${count} documents from ${collectionName} collection.`);
    return { count, success: true };
  } catch (error) {
    console.error(`Error deleting ${collectionName} collection:`, error);
    return { error: error.message, success: false };
  }
};

// Fonction pour vider toute la base de données
export const clearDatabase = async () => {
  console.log('Starting database clearing...');
  const results = {};
  
  // Supprimer la collection des animaux
  results.animals = await deleteCollection('animals');
  
  // Supprimer la collection des enregistrements d'alimentation
  results.feedings = await deleteCollection('feedings');
  
  console.log('Database clearing completed!');
  return results;
};

export default clearDatabase;
