import React, { useState } from 'react';
import { 
  Button, 
  Dialog, 
  DialogActions, 
  DialogContent, 
  DialogContentText, 
  DialogTitle,
  CircularProgress,
  Alert,
  Box,
  Typography
} from '@mui/material';
import { Delete as DeleteIcon } from '@mui/icons-material';
import { db } from '../../firebase/config';
import { collection, getDocs, deleteDoc, doc } from 'firebase/firestore';

const FEEDINGS_COLLECTION = 'feedings';

const DeleteAllFeedingsButton = () => {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(null);
  const [deletedCount, setDeletedCount] = useState(0);

  const handleClickOpen = () => {
    setOpen(true);
    setSuccess(false);
    setError(null);
    setDeletedCount(0);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleDeleteAll = async () => {
    setLoading(true);
    setSuccess(false);
    setError(null);
    
    try {
      // Récupérer tous les feedings
      const feedingsRef = collection(db, FEEDINGS_COLLECTION);
      const feedingsSnapshot = await getDocs(feedingsRef);
      
      console.log(`Suppression de tous les feedings (${feedingsSnapshot.size} trouvés)...`);
      
      // Supprimer chaque feeding
      const deletePromises = [];
      feedingsSnapshot.forEach((docSnapshot) => {
        const feedingRef = doc(db, FEEDINGS_COLLECTION, docSnapshot.id);
        deletePromises.push(deleteDoc(feedingRef));
      });
      
      // Attendre que toutes les suppressions soient terminées
      await Promise.all(deletePromises);
      
      setDeletedCount(feedingsSnapshot.size);
      setSuccess(true);
      console.log(`${feedingsSnapshot.size} feedings supprimés avec succès`);
    } catch (error) {
      console.error('Erreur lors de la suppression des feedings:', error);
      setError(error.message || 'Une erreur est survenue');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Button
        variant="contained"
        color="error"
        startIcon={<DeleteIcon />}
        onClick={handleClickOpen}
        fullWidth
        sx={{ mt: 2 }}
      >
        Delete ALL Feedings
      </Button>
      
      <Dialog open={open} onClose={loading ? null : handleClose}>
        <DialogTitle>Delete ALL Feeding Records</DialogTitle>
        <DialogContent>
          <DialogContentText>
            <Typography color="error" variant="subtitle1" fontWeight="bold" gutterBottom>
              WARNING: This will permanently delete ALL feeding records from the database.
            </Typography>
            <Typography variant="body2" paragraph>
              This action cannot be undone. All feeding history will be permanently lost.
            </Typography>
            <Typography variant="body2">
              Are you absolutely sure you want to proceed?
            </Typography>
          </DialogContentText>
          
          {loading && (
            <Box display="flex" justifyContent="center" my={2}>
              <CircularProgress color="error" />
            </Box>
          )}
          
          {success && (
            <Alert severity="success" sx={{ mt: 2 }}>
              Successfully deleted {deletedCount} feeding records.
            </Alert>
          )}
          
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose} color="inherit" disabled={loading}>
            Cancel
          </Button>
          <Button 
            onClick={handleDeleteAll} 
            color="error" 
            disabled={loading}
            variant="contained"
          >
            {loading ? 'Deleting...' : 'Delete All Feedings'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DeleteAllFeedingsButton;
