import React, { useState } from 'react';
import { 
  Card, 
  CardContent, 
  CardMedia, 
  Typography, 
  Box,
  Avatar,
  useTheme,
  IconButton
} from '@mui/material';
import { 
  Pets as PetsIcon,
  ZoomIn as ZoomInIcon
} from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { getRandomColor, getInitials } from '../../utils/animalImageService';
import ImageViewerModal from '../common/ImageViewerModal';

const AnimalCard = ({ animal }) => {
  const theme = useTheme();
  const avatarColor = React.useMemo(() => getRandomColor(), []);
  const [imageViewerOpen, setImageViewerOpen] = useState(false);

  return (
    <>
      <Card 
        component={Link}
        to={`/animals/${animal._id}`}
        sx={{
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          textDecoration: 'none',
          transition: 'transform 0.2s, box-shadow 0.2s',
          '&:hover': {
            transform: 'translateY(-4px)',
            boxShadow: 4,
          },
          position: 'relative',
          overflow: 'hidden',
          borderRadius: 2,
          minHeight: { xs: 280, sm: 320 },
          width: '100%',
        }}
      >
        {animal.image ? (
          <Box sx={{ position: 'relative' }}>
            <CardMedia
              component="img"
              height="160"
              image={animal.image}
              alt={animal.name}
              sx={{ 
                objectFit: 'cover',
                objectPosition: 'center',
              }}
            />
            <IconButton
              sx={{
                position: 'absolute',
                bottom: 8,
                right: 8,
                backgroundColor: 'rgba(0,0,0,0.5)',
                color: 'white',
                '&:hover': { backgroundColor: 'rgba(0,0,0,0.7)' },
                zIndex: 2,
              }}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                setImageViewerOpen(true);
              }}
            >
              <ZoomInIcon fontSize="small" />
            </IconButton>
          </Box>
        ) : (
          <Box
            sx={{
              height: 180,
              backgroundColor: theme.palette.grey[200],
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <Avatar 
              sx={{ 
                width: 80, 
                height: 80, 
                bgcolor: avatarColor,
                fontSize: '2rem'
              }}
            >
              {getInitials(animal.name)}
            </Avatar>
          </Box>
        )}
        
        <CardContent sx={{ flexGrow: 1, pt: 2 }}>
          <Typography variant="h6" component="h2" gutterBottom noWrap>
            {animal.name}
          </Typography>
          
          <Box display="flex" alignItems="center" mb={1}>
            <PetsIcon fontSize="small" color="action" sx={{ mr: 0.5, opacity: 0.7 }} />
            <Typography variant="body2" color="text.secondary" noWrap>
              {animal.species}
            </Typography>
          </Box>
          
          {animal.notes && (
            <Typography 
              variant="body2" 
              color="text.secondary" 
              sx={{
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
              }}
            >
              {animal.notes}
            </Typography>
          )}
        </CardContent>
      </Card>
      
      <ImageViewerModal
        open={imageViewerOpen}
        onClose={() => setImageViewerOpen(false)}
        imageUrl={animal.image}
        title={animal.name}
      />
    </>
  );
};

export default AnimalCard;
