import { db, storage } from './config';
import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  getDocs, 
  getDoc, 
  query, 
  where,
  orderBy,
  serverTimestamp
} from 'firebase/firestore';

// Collection pour les animaux
const ANIMALS_COLLECTION = 'animals';

/**
 * Récupère tous les animaux
 */
export const getAllAnimals = async () => {
  try {
    console.log('Fetching animals from Firestore...');
    const animalsRef = collection(db, ANIMALS_COLLECTION);
    console.log('Animals collection reference:', animalsRef);
    
    // Utiliser une requête simple sans orderBy pour simplifier
    const querySnapshot = await getDocs(animalsRef);
    console.log('Query snapshot received, empty?', querySnapshot.empty);
    
    const animals = [];
    querySnapshot.forEach((doc) => {
      console.log('Document found:', doc.id);
      animals.push({
        _id: doc.id,
        ...doc.data()
      });
    });
    
    // Trier les animaux par ordre alphabétique du nom
    animals.sort((a, b) => a.name.localeCompare(b.name));
    
    console.log('Total animals found:', animals.length);
    return { data: animals };
  } catch (error) {
    console.error('Error getting animals:', error);
    throw error;
  }
};

/**
 * Récupère un animal par son ID
 */
export const getAnimalById = async (animalId) => {
  try {
    console.log('Fetching animal with ID:', animalId);
    
    // Si l'ID est invalide ou manquant, essayons de récupérer le premier animal
    if (!animalId || animalId === 'undefined' || animalId === 'null') {
      console.log('Invalid animal ID, trying to get the first animal');
      const animalsRef = collection(db, ANIMALS_COLLECTION);
      const querySnapshot = await getDocs(animalsRef);
      
      if (querySnapshot.empty) {
        throw new Error('No animals found in the database');
      }
      
      // Prendre le premier animal
      const firstAnimalDoc = querySnapshot.docs[0];
      console.log('Found first animal with ID:', firstAnimalDoc.id);
      
      return {
        data: {
          _id: firstAnimalDoc.id,
          ...firstAnimalDoc.data()
        }
      };
    }
    
    // Sinon, récupérer l'animal avec l'ID spécifié
    const animalRef = doc(db, ANIMALS_COLLECTION, animalId);
    console.log('Animal reference:', animalRef);
    
    const animalDoc = await getDoc(animalRef);
    console.log('Animal document exists?', animalDoc.exists());
    
    if (!animalDoc.exists()) {
      console.log('Animal not found, trying to get the first animal');
      
      // Si l'animal n'existe pas, essayer de récupérer le premier animal
      const animalsRef = collection(db, ANIMALS_COLLECTION);
      const querySnapshot = await getDocs(animalsRef);
      
      if (querySnapshot.empty) {
        throw new Error('No animals found in the database');
      }
      
      // Prendre le premier animal
      const firstAnimalDoc = querySnapshot.docs[0];
      console.log('Found first animal with ID:', firstAnimalDoc.id);
      
      return {
        data: {
          _id: firstAnimalDoc.id,
          ...firstAnimalDoc.data()
        }
      };
    }
    
    const animalData = animalDoc.data();
    console.log('Animal data:', animalData);
    
    // Convertir les timestamps en dates
    const formattedData = {};
    
    // Convertir les timestamps en dates ISO
    Object.keys(animalData).forEach(key => {
      if (animalData[key] && typeof animalData[key] === 'object' && animalData[key].toDate) {
        formattedData[key] = animalData[key].toDate().toISOString();
      } else {
        formattedData[key] = animalData[key];
      }
    });
    
    return { 
      data: {
        _id: animalDoc.id,
        ...formattedData
      }
    };
  } catch (error) {
    console.error('Error getting animal:', error);
    throw error;
  }
};

/**
 * Crée un nouvel animal
 */
export const createAnimal = async (animalData) => {
  try {
    // Convertir l'image en base64 si elle existe
    let imageBase64 = null;
    if (animalData.image) {
      const reader = new FileReader();
      const promise = new Promise((resolve) => {
        reader.onload = (e) => {
          imageBase64 = e.target.result;
          resolve();
        };
        reader.readAsDataURL(animalData.image);
      });
      await promise;
    }
    
    // Préparer les données pour Firestore
    const animalToSave = {
      name: animalData.name,
      species: animalData.species,
      status: animalData.status || 'active',
      notes: animalData.notes || '',
      dateOfBirth: animalData.dateOfBirth || null,
      dateOfArrival: animalData.dateOfArrival || null,
      gender: animalData.gender || 'unknown',
      image: imageBase64,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp()
    };
    
    const docRef = await addDoc(collection(db, ANIMALS_COLLECTION), animalToSave);
    
    return { 
      data: {
        _id: docRef.id,
        ...animalToSave
      }
    };
  } catch (error) {
    console.error('Error creating animal:', error);
    throw error;
  }
};

/**
 * Met à jour un animal existant
 */
export const updateAnimal = async (animalId, animalData) => {
  try {
    const animalRef = doc(db, ANIMALS_COLLECTION, animalId);
    
    // Convertir l'image en base64 si elle existe
    let imageBase64 = null;
    
    // Si l'image est un Blob/File (nouvelle image uploadée)
    if (animalData.image && (animalData.image instanceof File || animalData.image instanceof Blob)) {
      const reader = new FileReader();
      const promise = new Promise((resolve) => {
        reader.onload = (e) => {
          imageBase64 = e.target.result;
          resolve();
        };
        reader.readAsDataURL(animalData.image);
      });
      await promise;
    } 
    // Si l'image est déjà une string (URL ou base64)
    else if (animalData.image && typeof animalData.image === 'string') {
      imageBase64 = animalData.image;
    }
    
    // Préparer les données pour Firestore
    const animalToUpdate = {
      name: animalData.name,
      species: animalData.species,
      status: animalData.status || 'active',
      notes: animalData.notes || '',
      dateOfBirth: animalData.dateOfBirth || null,
      dateOfArrival: animalData.dateOfArrival || null,
      gender: animalData.gender || 'unknown',
      updatedAt: serverTimestamp()
    };
    
    // Ajouter l'image uniquement si elle a été modifiée
    if (imageBase64) {
      animalToUpdate.image = imageBase64;
    } 
    // Si l'image doit être supprimée
    else if (animalData.image === null) {
      animalToUpdate.image = null;
    }
    
    await updateDoc(animalRef, animalToUpdate);
    
    // Récupérer l'animal mis à jour
    const updatedAnimal = await getDoc(animalRef);
    
    return { 
      data: {
        _id: updatedAnimal.id,
        ...updatedAnimal.data()
      }
    };
  } catch (error) {
    console.error('Error updating animal:', error);
    throw error;
  }
};

/**
 * Supprime un animal
 */
export const deleteAnimal = async (animalId) => {
  try {
    await deleteDoc(doc(db, ANIMALS_COLLECTION, animalId));
    return { success: true };
  } catch (error) {
    console.error('Error deleting animal:', error);
    throw error;
  }
};
