import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Grid, 
  Card, 
  CardContent, 
  Typography, 
  CircularProgress,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Divider,
  Chip,
  useTheme,
  useMediaQuery,
  Alert
} from '@mui/material';
import { 
  Pets as PetsIcon, 
  Restaurant as RestaurantIcon, 
  CheckCircle as CheckCircleIcon,
  Pending as PendingIcon,
  Add as AddIcon
} from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { getAnimals, getFeedings } from '../api/api';

const Dashboard = () => {
  const [stats, setStats] = useState({
    totalAnimals: 0,
    totalFeedings: 0,
    feedingsToday: 0,
    pendingFeedings: 0,
  });
  const [recentFeedings, setRecentFeedings] = useState([]);
  const [loading, setLoading] = useState(true);
  // États pour le graphique supprimés
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        
        // Fetch animals
        const animalsRes = await getAnimals();
        const animals = animalsRes.data;
        
        // Fetch feedings
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        
        const feedingsRes = await getFeedings();
        const allFeedings = feedingsRes.data || [];
        
        const todayFeedings = allFeedings.filter(feeding => {
          const feedingDate = new Date(feeding.date);
          return feedingDate >= today;
        });
        
        setStats({
          totalAnimals: animals.length,
          totalFeedings: allFeedings.length,
          feedingsToday: todayFeedings.length,
          pendingFeedings: animals.length - todayFeedings.length,
        });
        
        // Get recent feedings (last 5)
        const sortedFeedings = [...allFeedings]
          .sort((a, b) => new Date(b.date) - new Date(a.date))
          .slice(0, 5);
          
        setRecentFeedings(sortedFeedings);
        // Préparation des données pour le graphique supprimée
        
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, []);

  // Fonctions liées au graphique supprimées
  
  
  const StatCard = ({ title, value, icon, color }) => (
    <Card 
      elevation={2} 
      sx={{ 
        height: '100%',
        borderLeft: `4px solid ${color}`,
        borderRadius: 1,
        '&:hover': {
          boxShadow: 3,
        },
      }}
    >
      <CardContent sx={{ p: isMobile ? 1.5 : 2 }}>
        <Box display="flex" alignItems="center">
          <Box
            sx={{
              backgroundColor: `${color}20`,
              borderRadius: '50%',
              width: isMobile ? 40 : 48,
              height: isMobile ? 40 : 48,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mr: isMobile ? 1.5 : 2,
              flexShrink: 0,
            }}
          >
            {React.cloneElement(icon, { style: { color, fontSize: isMobile ? 24 : 28 } })}
          </Box>
          <Box sx={{ overflow: 'hidden' }}>
            <Typography color="textSecondary" variant="body2" noWrap>
              {title}
            </Typography>
            <Typography variant="h6" component="div" noWrap>
              {loading ? <CircularProgress size={20} /> : value}
            </Typography>
          </Box>
        </Box>
      </CardContent>
    </Card>
  );

  return (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h5" gutterBottom>
          Dashboard
        </Typography>
      </Box>
      
      {stats.totalAnimals === 0 && !loading && (
        <Alert severity="info" sx={{ mb: 3 }}>
          Your database is empty. Go to the Settings page to initialize the database with test data.
        </Alert>
      )}
      
      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={6} sm={6} md={3}>
          <StatCard 
            title="Total Animals" 
            value={stats.totalAnimals} 
            icon={<PetsIcon />} 
            color={theme.palette.primary.main}
          />
        </Grid>
        <Grid item xs={6} sm={6} md={3}>
          <StatCard 
            title="Feedings Today" 
            value={`${stats.feedingsToday}/${stats.totalAnimals}`} 
            icon={<RestaurantIcon />} 
            color={theme.palette.success.main}
          />
        </Grid>
        <Grid item xs={6} sm={6} md={3}>
          <StatCard 
            title="Pending Feedings" 
            value={stats.pendingFeedings} 
            icon={<PendingIcon />} 
            color={theme.palette.warning.main}
          />
        </Grid>
        <Grid item xs={6} sm={6} md={3}>
          <StatCard 
            title="Total Feedings" 
            value={stats.totalFeedings} 
            icon={<CheckCircleIcon />} 
            color={theme.palette.info.main}
          />
        </Grid>
      </Grid>
         
      <Grid container spacing={3}>
        {/* Recent Feedings */}
        <Grid item xs={12} md={8}>
          <Paper elevation={2} sx={{ p: 2, borderRadius: 2 }}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="h6">Recent Feedings</Typography>
              <Button 
                component={Link} 
                to="/feedings/new" 
                variant="contained" 
                size="small"
                startIcon={<AddIcon />}
              >
                New Feeding
              </Button>
            </Box>
            <Divider sx={{ mb: 2 }} />
            {loading ? (
              <Box display="flex" justifyContent="center" p={3}>
                <CircularProgress />
              </Box>
            ) : recentFeedings.length > 0 ? (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Animal</TableCell>
                      <TableCell>Time</TableCell>
                      <TableCell>Status</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {recentFeedings.map((feeding) => (
                      <TableRow 
                        key={feeding._id} 
                        hover 
                        component={Link}
                        to={`/feedings/${feeding._id}`}
                        sx={{ 
                          textDecoration: 'none',
                          '&:hover': {
                            backgroundColor: 'action.hover',
                          },
                        }}
                      >
                        <TableCell>
                          <Box display="flex" alignItems="center">
                            <PetsIcon fontSize="small" sx={{ mr: 1, color: 'text.secondary' }} />
                            <Typography variant="body2">
                              {feeding.animal?.name || 'Unknown'}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell>
                          <Typography variant="body2">
                            {new Date(feeding.date).toLocaleTimeString([], { 
                              hour: '2-digit', 
                              minute: '2-digit' 
                            })}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <Chip 
                            label={feeding.status} 
                            size="small" 
                            color={
                              feeding.status === 'completed' ? 'success' : 
                              feeding.status === 'pending' ? 'warning' : 'default'
                            }
                            sx={{ textTransform: 'capitalize' }}
                          />
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            ) : (
              <Box p={3} textAlign="center">
                <Typography color="textSecondary">
                  No feeding records found. Add your first feeding!
                </Typography>
              </Box>
            )}
            <Box mt={2} display="flex" justifyContent="flex-end">
              <Button 
                component={Link} 
                to="/feedings" 
                size="small"
                sx={{ mt: 1 }}
              >
                View All Feedings
              </Button>
            </Box>
          </Paper>
        </Grid>
        
        {/* Quick Actions */}
        <Grid item xs={12} md={4}>
          <Paper elevation={2} sx={{ p: 2, borderRadius: 2, height: '100%' }}>
            <Typography variant="h6" gutterBottom>
              Quick Actions
            </Typography>
            <Divider sx={{ mb: 2 }} />
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Button
                  component={Link}
                  to="/animals/new"
                  variant="outlined"
                  fullWidth
                  startIcon={<PetsIcon />}
                  sx={{ justifyContent: 'flex-start', py: 1.5, mb: 1 }}
                >
                  Add New Animal
                </Button>
              </Grid>
              <Grid item xs={12}>
                <Button
                  component={Link}
                  to="/feedings/new"
                  variant="contained"
                  color="primary"
                  fullWidth
                  startIcon={<RestaurantIcon />}
                  sx={{ justifyContent: 'flex-start', py: 1.5, mb: 1 }}
                >
                  Record Feeding
                </Button>
              </Grid>
              <Grid item xs={12}>
                <Button
                  component={Link}
                  to="/animals"
                  variant="outlined"
                  fullWidth
                  startIcon={<PetsIcon />}
                  sx={{ justifyContent: 'flex-start', py: 1.5 }}
                >
                  View All Animals
                </Button>
              </Grid>
            </Grid>
            
            <Box mt={4}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                Today's Summary
              </Typography>
              <Box display="flex" justifyContent="space-between" mb={1}>
                <Typography variant="body2">Total Animals:</Typography>
                <Typography variant="body2" fontWeight="medium">
                  {stats.totalAnimals}
                </Typography>
              </Box>
              <Box display="flex" justifyContent="space-between" mb={1}>
                <Typography variant="body2">Fed Today:</Typography>
                <Typography 
                  variant="body2" 
                  fontWeight="medium"
                  color={stats.feedingsToday === stats.totalAnimals ? 'success.main' : 'text.primary'}
                >
                  {stats.feedingsToday} / {stats.totalAnimals}
                </Typography>
              </Box>
              <Box display="flex" justifyContent="space-between">
                <Typography variant="body2">Completion:</Typography>
                <Typography variant="body2" fontWeight="medium">
                  {stats.totalAnimals > 0 
                    ? Math.round((stats.feedingsToday / stats.totalAnimals) * 100) 
                    : 0}%
                </Typography>
              </Box>
            </Box>
            
            <Box mt={4}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                Quick Stats
              </Typography>
              <Box display="flex" justifyContent="space-between" mb={1}>
                <Typography variant="body2">Animals to Feed:</Typography>
                <Typography variant="body2" fontWeight="medium" color="warning.main">
                  {stats.pendingFeedings}
                </Typography>
              </Box>
              <Box display="flex" justifyContent="space-between">
                <Typography variant="body2">Total Feedings:</Typography>
                <Typography variant="body2" fontWeight="medium">
                  {stats.totalFeedings}
                </Typography>
              </Box>
            </Box>
          </Paper>
        </Grid>

      {/* Section du graphique supprimée */}
      </Grid>
    </Box>
  );
};

export default Dashboard;
