import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Typography, 
  Paper, 
  Grid, 
  Button, 
  Chip, 
  Divider, 
  Tabs, 
  Tab,
  CircularProgress,
  useTheme,
  useMediaQuery,
  Avatar,
  Card,
  CardContent,
  CardHeader,
  IconButton,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
} from '@mui/material';
import { 
  Edit as EditIcon, 
  ArrowBack as ArrowBackIcon,
  Pets as PetsIcon,
  Restaurant as RestaurantIcon,
  AccessTime as AccessTimeIcon,
  ZoomIn as ZoomInIcon,
  EventNote as EventNoteIcon,
  Info as InfoIcon,
  MedicalServices as MedicalServicesIcon,
} from '@mui/icons-material';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getAnimalById, getFeedings, getAnimals, getMedicalActions } from '../api/api';
import format from 'date-fns/format';
import isValid from 'date-fns/isValid';
import ImageViewerModal from '../components/common/ImageViewerModal';

// Fonction utilitaire pour formater les dates en toute sécurité
const safeFormatDate = (dateValue, formatString) => {
  if (!dateValue) return 'N/A';
  
  try {
    // Si c'est un objet Firestore Timestamp
    if (typeof dateValue === 'object' && dateValue.toDate) {
      const date = dateValue.toDate();
      if (isValid(date)) {
        return format(date, formatString);
      }
    }
    
    // Si c'est une chaîne de caractères ou un timestamp
    const date = new Date(dateValue);
    if (isValid(date)) {
      return format(date, formatString);
    }
    
    return 'Invalid date';
  } catch (error) {
    console.error('Error formatting date:', error);
    return 'Error';
  }
};

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`animal-tabpanel-${index}`}
      aria-labelledby={`animal-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box p={3}>
          {children}
        </Box>
      )}
    </div>
  );
}

function a11yProps(index) {
  return {
    id: `animal-tab-${index}`,
    'aria-controls': `animal-tabpanel-${index}`,
  };
}

const AnimalDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [animal, setAnimal] = useState(null);
  const [feedings, setFeedings] = useState([]);
  const [medicalActions, setMedicalActions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingFeedings, setLoadingFeedings] = useState(true);
  const [loadingMedical, setLoadingMedical] = useState(true);
  const [imageViewerOpen, setImageViewerOpen] = useState(false);
  const [currentImage, setCurrentImage] = useState({ url: '', title: '' });
  const [tabValue, setTabValue] = useState(0);

  useEffect(() => {
    const fetchAnimal = async () => {
      try {
        setLoading(true);
        const response = await getAnimalById(id);
        setAnimal(response.data);
      } catch (error) {
        console.error('Error getting animal:', error);
        navigate('/animals');
      } finally {
        setLoading(false);
      }
    };

    fetchAnimal();
  }, [id, navigate]);

  useEffect(() => {
    const fetchFeedings = async () => {
      if (!animal) return;
      
      try {
        setLoadingFeedings(true);
        console.log('Fetching feedings for animal:', animal._id, animal.name);
        console.log('Animal ID type:', typeof animal._id);
        
        // Force l'ID à être une chaîne
        const animalId = String(animal._id);
        console.log('Normalized animalId:', animalId);
        
        const response = await getFeedings({ animalId });
        console.log('Feedings response:', response);
        setFeedings(response.data || []);
        console.log('Feedings set:', response.data || []);
      } catch (error) {
        console.error('Error getting feedings:', error);
      } finally {
        setLoadingFeedings(false);
      }
    };

    fetchFeedings();
  }, [animal]);

  useEffect(() => {
    const fetchMedical = async () => {
      if (!animal) return;

      try {
        setLoadingMedical(true);
        const animalId = String(animal._id);
        const response = await getMedicalActions({ animalId });
        if (response && response.success) {
          setMedicalActions(response.data || []);
        } else {
          setMedicalActions([]);
        }
      } catch (error) {
        console.error('Error getting medical actions:', error);
        setMedicalActions([]);
      } finally {
        setLoadingMedical(false);
      }
    };

    fetchMedical();
  }, [animal]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  // Fonction de statut supprimée car nous n'utilisons plus le statut

  if (loading || !animal) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ pb: 6 }}>
      {/* Header with back button and actions */}
      <Box 
        sx={{
          display: 'flex', 
          alignItems: 'center', 
          mb: 2,
          position: 'sticky',
          top: 0,
          bgcolor: 'background.paper',
          zIndex: 10,
          py: 1
        }}
      >
        <IconButton component={Link} to="/animals">
          <ArrowBackIcon />
        </IconButton>
        <Typography variant="h6" component="h1" sx={{ ml: 1 }}>
          {animal.name}
        </Typography>
        <Box flexGrow={1} />
        <IconButton 
          color="primary" 
          onClick={() => navigate(`/animals/${animal._id}/edit`)}
          aria-label="Edit animal"
        >
          <EditIcon />
        </IconButton>
      </Box>

      {/* Animal header with image */}
      <Box 
        sx={{
          position: 'relative',
          mb: 2,
          bgcolor: 'background.paper',
          borderRadius: 1,
          overflow: 'hidden',
          boxShadow: 1,
          display: 'flex',
          flexDirection: { xs: 'column', sm: 'row' },
        }}
      >
        {/* Image container - plus grand et adaptatif */}
        <Box 
          sx={{
            flex: { xs: '1 1 auto', sm: '0 0 50%' },
            maxHeight: { xs: '300px', sm: '400px' },
            backgroundColor: theme.palette.grey[200],
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            overflow: 'hidden',
            position: 'relative',
          }}
        >
          {animal.image ? (
            <img
              src={animal.image}
              alt={animal.name}
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'contain', // 'contain' au lieu de 'cover' pour voir l'image entière
                maxHeight: '400px',
              }}
            />
          ) : (
            <PetsIcon sx={{ fontSize: 80, color: theme.palette.grey[400] }} />
          )}
          {/* Bouton de zoom */}
          {animal.image && (
            <IconButton
              sx={{
                position: 'absolute',
                bottom: 8,
                right: 8,
                backgroundColor: 'rgba(0,0,0,0.5)',
                color: 'white',
                '&:hover': { backgroundColor: 'rgba(0,0,0,0.7)' },
              }}
              onClick={() => {
                setCurrentImage({ url: animal.image, title: animal.name });
                setImageViewerOpen(true);
              }}
            >
              <ZoomInIcon />
            </IconButton>
          )}
        </Box>
        
        <Box sx={{ p: 2, flex: '1 1 auto', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <Typography variant="h6">
              {animal.name}
            </Typography>
            {/* Chip de statut supprimé */}
          </Box>
          
          <Typography variant="body1" color="text.secondary">
            {animal.species}
          </Typography>
          
          <Box sx={{ display: 'flex', mt: 2, color: 'text.secondary' }}>
            <Box sx={{ display: 'flex', alignItems: 'center', mr: 3 }}>
              <AccessTimeIcon fontSize="small" sx={{ mr: 0.5 }} />
              <Typography variant="body2">
                {`DOB: ${safeFormatDate(animal.dateOfBirth, 'MMM d, yyyy')}`}
              </Typography>
            </Box>

            <Box sx={{ display: 'flex', alignItems: 'center', mr: 3 }}>
              <EventNoteIcon fontSize="small" sx={{ mr: 0.5 }} />
              <Typography variant="body2">
                {`Arrival: ${safeFormatDate(animal.dateOfArrival, 'MMM d, yyyy')}`}
              </Typography>
            </Box>

            <Box sx={{ display: 'flex', alignItems: 'center', mr: 3 }}>
              <InfoIcon fontSize="small" sx={{ mr: 0.5 }} />
              <Typography variant="body2">
                {`Gender: ${animal.gender || 'unknown'}`}
              </Typography>
            </Box>
            
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <RestaurantIcon fontSize="small" sx={{ mr: 0.5 }} />
              <Typography variant="body2">
                {feedings.length > 0 ? safeFormatDate(feedings[0].date, 'MMM d, yyyy') : 'No feedings'}
              </Typography>
            </Box>
          </Box>
        </Box>
      </Box>

      {/* Tabs - Mobile friendly */}
      <Box sx={{ bgcolor: 'background.paper', boxShadow: 1, borderRadius: 1, mb: 2 }}>
        <Tabs
          value={tabValue}
          onChange={handleTabChange}
          aria-label="animal detail tabs"
          variant="fullWidth"
          sx={{ borderBottom: 1, borderColor: 'divider' }}
        >
          <Tab label="Feedings" {...a11yProps(0)} />
          <Tab label="Notes" {...a11yProps(1)} />
          <Tab label="Medical" {...a11yProps(2)} />
        </Tabs>
        
        <TabPanel value={tabValue} index={0}>
          {loadingFeedings ? (
            <Box display="flex" justifyContent="center" p={3}>
              <CircularProgress />
            </Box>
          ) : feedings.length > 0 ? (
            <Box>
              {feedings.map((feeding) => (
                <Box 
                  key={feeding._id}
                  sx={{
                    p: 2,
                    borderBottom: '1px solid',
                    borderColor: 'divider',
                    cursor: 'pointer',
                    '&:hover': {
                      bgcolor: 'action.hover',
                    },
                  }}
                  onClick={() => navigate(`/feedings/${feeding._id}`)}
                >
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                    <Typography variant="subtitle2">
                      {safeFormatDate(feeding.date, 'MMM d, yyyy')}
                    </Typography>
                    <Chip 
                      label={feeding.status}
                      size="small"
                      color={
                        feeding.status === 'completed' ? 'success' :
                        feeding.status === 'pending' ? 'warning' : 'default'
                      }
                      sx={{ textTransform: 'capitalize' }}
                    />
                  </Box>
                  <Box sx={{ display: 'flex', alignItems: 'center' }}>
                    <AccessTimeIcon fontSize="small" sx={{ mr: 0.5, color: 'text.secondary' }} />
                    <Typography variant="body2" color="text.secondary">
                      {safeFormatDate(feeding.date, 'h:mm a')}
                    </Typography>
                  </Box>
                </Box>
              ))}
            </Box>
          ) : (
            <Box textAlign="center" p={3}>
              <RestaurantIcon sx={{ fontSize: 48, color: 'text.disabled', mb: 1 }} />
              <Typography variant="body1" color="text.secondary" gutterBottom>
                No feeding records found
              </Typography>
              <Button
                variant="outlined"
                color="primary"
                component={Link}
                to={`/feedings/new?animalId=${animal._id}`}
                startIcon={<RestaurantIcon />}
                sx={{ mt: 1 }}
              >
                Record Feeding
              </Button>
            </Box>
          )}
        </TabPanel>
        
        <TabPanel value={tabValue} index={1}>
          {animal.notes ? (
            <Box p={2}>
              <Typography variant="body1" sx={{ whiteSpace: 'pre-line' }}>
                {animal.notes}
              </Typography>
            </Box>
          ) : (
            <Box textAlign="center" p={3}>
              <InfoIcon sx={{ fontSize: 48, color: 'text.disabled', mb: 1 }} />
              <Typography variant="body1" color="text.secondary">
                No notes available for this animal
              </Typography>
            </Box>
          )}
        </TabPanel>

        <TabPanel value={tabValue} index={2}>
          {loadingMedical ? (
            <Box display="flex" justifyContent="center" p={3}>
              <CircularProgress />
            </Box>
          ) : (() => {
            const now = new Date();

            const upcoming = (medicalActions || [])
              .filter((a) => {
                if (!a?.nextDueDate) return false;
                const d = new Date(a.nextDueDate);
                return isValid(d) && d >= now;
              })
              .sort((a, b) => new Date(a.nextDueDate) - new Date(b.nextDueDate));

            const history = (medicalActions || [])
              .slice()
              .sort((a, b) => {
                const da = a?.date ? new Date(a.date) : new Date(0);
                const db = b?.date ? new Date(b.date) : new Date(0);
                return db - da;
              });

            const typeLabel = (type) => {
              switch (type) {
                case 'vaccination':
                  return 'Vaccination';
                case 'treatment':
                  return 'Treatment';
                case 'checkup':
                  return 'Checkup';
                default:
                  return 'Other';
              }
            };

            return (
              <Box>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <MedicalServicesIcon color="primary" />
                    <Typography variant="subtitle1" fontWeight="medium">
                      Medical
                    </Typography>
                  </Box>
                  <Button
                    variant="outlined"
                    component={Link}
                    to="/medical/new"
                    size="small"
                  >
                    Add medical action
                  </Button>
                </Box>

                <Paper elevation={0} sx={{ p: 2, mb: 2, border: '1px solid', borderColor: 'divider', borderRadius: 2 }}>
                  <Typography variant="subtitle2" gutterBottom>
                    Upcoming
                  </Typography>
                  <Divider sx={{ mb: 1 }} />
                  {upcoming.length > 0 ? (
                    <List disablePadding>
                      {upcoming.map((a) => (
                        <ListItem
                          key={a._id}
                          disableGutters
                          sx={{
                            py: 1,
                            px: 1,
                            borderRadius: 1,
                            cursor: 'pointer',
                            '&:hover': { bgcolor: 'action.hover' },
                          }}
                          onClick={() => navigate(`/medical/${a._id}`)}
                        >
                          <ListItemIcon sx={{ minWidth: 36 }}>
                            <MedicalServicesIcon fontSize="small" color="action" />
                          </ListItemIcon>
                          <ListItemText
                            primary={a.name || 'Medical action'}
                            secondary={`Next: ${safeFormatDate(a.nextDueDate, 'MMM d, yyyy')}`}
                          />
                          <Chip label={typeLabel(a.type)} size="small" sx={{ textTransform: 'capitalize' }} />
                        </ListItem>
                      ))}
                    </List>
                  ) : (
                    <Typography variant="body2" color="text.secondary">
                      No upcoming medical actions.
                    </Typography>
                  )}
                </Paper>

                <Paper elevation={0} sx={{ p: 2, border: '1px solid', borderColor: 'divider', borderRadius: 2 }}>
                  <Typography variant="subtitle2" gutterBottom>
                    History
                  </Typography>
                  <Divider sx={{ mb: 1 }} />
                  {history.length > 0 ? (
                    <List disablePadding>
                      {history.map((a) => (
                        <ListItem
                          key={a._id}
                          disableGutters
                          sx={{
                            py: 1,
                            px: 1,
                            borderRadius: 1,
                            cursor: 'pointer',
                            '&:hover': { bgcolor: 'action.hover' },
                          }}
                          onClick={() => navigate(`/medical/${a._id}`)}
                        >
                          <ListItemIcon sx={{ minWidth: 36 }}>
                            <MedicalServicesIcon fontSize="small" color="action" />
                          </ListItemIcon>
                          <ListItemText
                            primary={a.name || 'Medical action'}
                            secondary={`Date: ${safeFormatDate(a.date || a.createdAt, 'MMM d, yyyy')}`}
                          />
                          <Chip label={typeLabel(a.type)} size="small" sx={{ textTransform: 'capitalize' }} />
                        </ListItem>
                      ))}
                    </List>
                  ) : (
                    <Box textAlign="center" p={2}>
                      <MedicalServicesIcon sx={{ fontSize: 40, color: 'text.disabled', mb: 1 }} />
                      <Typography variant="body2" color="text.secondary">
                        No medical records found.
                      </Typography>
                    </Box>
                  )}
                </Paper>
              </Box>
            );
          })()}
        </TabPanel>
      </Box>
      
      {/* Fixed action buttons at bottom */}
      <Box 
        sx={{
          position: 'fixed',
          bottom: 16,
          right: 16,
          zIndex: 2,
          display: 'flex',
          flexDirection: 'column',
          gap: 1
        }}
      >
        <Button
          variant="contained"
          color="secondary"
          startIcon={<RestaurantIcon />}
          onClick={() => navigate(`/feedings/new?animalId=${animal._id}`)}
          sx={{ boxShadow: 3 }}
        >
          Record Feeding
        </Button>
        
        <Button
          variant="contained"
          color="primary"
          startIcon={<EditIcon />}
          onClick={() => navigate(`/animals/${animal._id}/edit`)}
          sx={{ boxShadow: 3 }}
        >
          Edit Animal
        </Button>
      </Box>
      
      {/* Modal pour afficher l'image en grand format */}
      <ImageViewerModal
        open={imageViewerOpen}
        onClose={() => setImageViewerOpen(false)}
        imageUrl={currentImage.url}
        title={currentImage.title}
      />
    </Box>
  );
};

export default AnimalDetail;
