import React, { useState, useEffect } from 'react';
import { 
  Dialog, 
  DialogContent, 
  IconButton, 
  Box,
  AppBar,
  Toolbar,
  Typography
} from '@mui/material';
import { 
  Close as CloseIcon,
  ZoomIn as ZoomInIcon,
  ZoomOut as ZoomOutIcon,
  Fullscreen as FullscreenIcon,
  FullscreenExit as FullscreenExitIcon
} from '@mui/icons-material';

/**
 * Modal component for viewing images in full size
 */
const ImageViewerModal = ({ open, onClose, imageUrl, title }) => {
  const [zoom, setZoom] = useState(1.5);
  const [fitToScreen, setFitToScreen] = useState(true);
  
  // Reset zoom when modal opens or image changes
  useEffect(() => {
    if (open) {
      setZoom(1.5);
      setFitToScreen(true);
    }
  }, [open, imageUrl]);
  
  const handleZoomIn = (e) => {
    e.stopPropagation();
    setZoom(prev => Math.min(prev + 0.25, 3));
    setFitToScreen(false);
  };
  
  const handleZoomOut = (e) => {
    e.stopPropagation();
    setZoom(prev => Math.max(prev - 0.25, 0.5));
    setFitToScreen(false);
  };
  
  const toggleFitToScreen = (e) => {
    e.stopPropagation();
    setFitToScreen(!fitToScreen);
    if (!fitToScreen) setZoom(1);
  };
  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth={false}
      fullWidth
      PaperProps={{
        sx: {
          width: '98vw',
          height: '98vh',
          maxWidth: '98vw',
          maxHeight: '98vh',
          bgcolor: 'background.paper',
          m: 'auto',
          overflow: 'hidden'
        }
      }}
    >
      <AppBar position="relative" color="primary" elevation={0} sx={{ minHeight: '48px' }}>
        <Toolbar sx={{ minHeight: '48px' }}>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            {title || 'Image Viewer'}
          </Typography>
          
          <IconButton color="inherit" onClick={handleZoomOut} disabled={zoom <= 0.5} title="Zoom out">
            <ZoomOutIcon />
          </IconButton>
          
          <IconButton color="inherit" onClick={handleZoomIn} disabled={zoom >= 3} title="Zoom in">
            <ZoomInIcon />
          </IconButton>
          
          <IconButton color="inherit" onClick={toggleFitToScreen} title={fitToScreen ? "Actual size" : "Fit to screen"}>
            {fitToScreen ? <FullscreenExitIcon /> : <FullscreenIcon />}
          </IconButton>
          
          <IconButton
            edge="end"
            color="inherit"
            onClick={onClose}
            aria-label="close"
          >
            <CloseIcon />
          </IconButton>
        </Toolbar>
      </AppBar>
      <DialogContent sx={{ 
        p: 0, 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'center', 
        bgcolor: '#1a1a1a',
        height: 'calc(98vh - 48px)', // Subtract AppBar height
        overflow: 'hidden'
      }}>
        <Box 
          component="img"
          src={imageUrl}
          alt={title || "Image"}
          sx={{
            maxWidth: fitToScreen ? '100%' : 'none',
            maxHeight: fitToScreen ? 'calc(98vh - 48px)' : 'none', // Subtract AppBar height
            width: fitToScreen ? '100%' : `${zoom * 100}%`,
            height: fitToScreen ? '100%' : 'auto',
            objectFit: 'contain',
            boxShadow: '0 0 20px rgba(0,0,0,0.2)',
            borderRadius: 1,
            transition: 'transform 0.2s ease-out',
            cursor: zoom > 1.5 ? 'zoom-out' : 'zoom-in',
          }}
          onClick={() => setZoom(zoom > 1.5 ? 1.5 : 2)}
        />
      </DialogContent>
    </Dialog>
  );
};

export default ImageViewerModal;
