import React, { useState } from 'react';
import { 
  Button, 
  Dialog, 
  DialogActions, 
  DialogContent, 
  DialogContentText, 
  DialogTitle,
  TextField,
  Box,
  CircularProgress,
  Alert
} from '@mui/material';
import { db } from '../../firebase/config';
import { collection, addDoc, serverTimestamp } from 'firebase/firestore';

const InitializeDatabase = () => {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [animalName, setAnimalName] = useState('Lion');
  const [animalSpecies, setAnimalSpecies] = useState('Panthera leo');
  const [animalEnclosure, setAnimalEnclosure] = useState('Savanna Zone');

  const handleOpen = () => {
    setOpen(true);
    setSuccess(false);
    setError('');
  };

  const handleClose = () => {
    setOpen(false);
  };

  const initializeDatabase = async () => {
    try {
      setLoading(true);
      setSuccess(false);
      setError('');

      // Ajouter un animal de test
      const animalData = {
        name: animalName,
        species: animalSpecies,
        enclosure: animalEnclosure,
        status: 'active',
        notes: 'This is a test animal created for initialization.',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      };

      const animalRef = await addDoc(collection(db, 'animals'), animalData);
      console.log('Animal added with ID:', animalRef.id);

      // Ajouter un enregistrement d'alimentation de test
      const feedingData = {
        animalId: animalRef.id,
        date: new Date(),
        status: 'completed',
        notes: 'This is a test feeding record created for initialization.',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      };

      const feedingRef = await addDoc(collection(db, 'feedings'), feedingData);
      console.log('Feeding added with ID:', feedingRef.id);

      setSuccess(true);
    } catch (err) {
      console.error('Error initializing database:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Button 
        variant="contained" 
        color="primary" 
        onClick={handleOpen}
        sx={{ mt: 2 }}
      >
        Initialize Database with Test Data
      </Button>
      
      <Dialog open={open} onClose={handleClose}>
        <DialogTitle>Initialize Database</DialogTitle>
        <DialogContent>
          <DialogContentText>
            This will create a test animal and feeding record in your Firebase database.
            You can customize the animal details below:
          </DialogContentText>
          
          <Box sx={{ mt: 2 }}>
            <TextField
              autoFocus
              margin="dense"
              label="Animal Name"
              fullWidth
              variant="outlined"
              value={animalName}
              onChange={(e) => setAnimalName(e.target.value)}
            />
            <TextField
              margin="dense"
              label="Species"
              fullWidth
              variant="outlined"
              value={animalSpecies}
              onChange={(e) => setAnimalSpecies(e.target.value)}
            />
            <TextField
              margin="dense"
              label="Enclosure"
              fullWidth
              variant="outlined"
              value={animalEnclosure}
              onChange={(e) => setAnimalEnclosure(e.target.value)}
            />
          </Box>
          
          {success && (
            <Alert severity="success" sx={{ mt: 2 }}>
              Database initialized successfully!
            </Alert>
          )}
          
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              Error: {error}
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button 
            onClick={initializeDatabase} 
            color="primary" 
            disabled={loading || !animalName || !animalSpecies || !animalEnclosure}
            startIcon={loading ? <CircularProgress size={20} /> : null}
          >
            {loading ? 'Initializing...' : 'Initialize'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default InitializeDatabase;
