import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Button, 
  TextField, 
  Typography, 
  Paper, 
  Grid, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  FormHelperText,
  CircularProgress,
  Divider,
  useTheme,
  IconButton,
  Card,
  CardContent,
  Chip,
  FormControlLabel,
  Checkbox,
  Alert,
  Tooltip,
  Switch
} from '@mui/material';
import { 
  Save as SaveIcon, 
  ArrowBack as ArrowBackIcon,
  Delete as DeleteIcon,
  MedicalServices as MedicalIcon,
  CalendarMonth as CalendarIcon,
  Vaccines as VaccineIcon
} from '@mui/icons-material';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import { getAnimalById, getAnimals, getMedicalActionById, createMedicalAction, updateMedicalAction } from '../api/api';
import ConfirmationDialog from '../components/common/ConfirmationDialog';
import format from 'date-fns/format';
import addMonths from 'date-fns/addMonths';

// Schéma de validation
const validationSchema = Yup.object({
  animal: Yup.string().required('Animal required'),
  type: Yup.string().required('Type required'),
  name: Yup.string().required('Name required'),
  date: Yup.date().required('Date required'),
  notes: Yup.string(),
  nextDueDate: Yup.date().nullable(),
  frequency: Yup.number().min(1, 'Frequency must be at least 1').nullable(),
});

const MedicalForm = ({ isEdit = false }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const theme = useTheme();
  const [loading, setLoading] = useState(isEdit);
  const [animals, setAnimals] = useState([]);
  const [selectedAnimal, setSelectedAnimal] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [hasNextDueDate, setHasNextDueDate] = useState(!isEdit);

  // Initialiser le formulaire avec Formik
  const formik = useFormik({
    initialValues: {
      animal: '',
      type: 'vaccination',
      name: '',
      date: format(new Date(), 'yyyy-MM-dd'),
      notes: '',
      nextDueDate: '',
      frequency: 12, // Fréquence par défaut en mois
    },
    validationSchema,
    onSubmit: async (values) => {
      try {
        setLoading(true);

        const shouldSchedule = hasNextDueDate || values.type === 'vaccination';
        const computedNextDueDate =
          shouldSchedule && values.date && values.frequency
            ? format(addMonths(new Date(values.date), parseInt(values.frequency)), 'yyyy-MM-dd')
            : '';
        
        // Préparer les données
        const medicalData = {
          animalId: String(values.animal),
          type: values.type,
          name: values.name,
          date: new Date(values.date).toISOString(),
          notes: values.notes,
          nextDueDate: shouldSchedule
            ? new Date((values.nextDueDate || computedNextDueDate)).toISOString()
            : null,
          frequency: shouldSchedule ? values.frequency : null,
        };
        
        // Créer ou mettre à jour l'action médicale
        let response;
        if (isEdit) {
          response = await updateMedicalAction(id, medicalData);
        } else {
          response = await createMedicalAction(medicalData);
        }
        
        if (response.success) {
          navigate('/medical');
        } else {
          console.error('Error saving medical action:', response.error);
          // Afficher une erreur
        }
      } catch (error) {
        console.error('Error saving medical action:', error);
      } finally {
        setLoading(false);
      }
    },
  });

  // Charger les données au chargement
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        
        // Récupérer la liste des animaux
        const animalsRes = await getAnimals();
        if (animalsRes && animalsRes.data) {
          setAnimals(animalsRes.data);
        }
        
        // Si en mode édition, récupérer l'action médicale
        if (isEdit && id) {
          const medicalRes = await getMedicalActionById(id);
          if (medicalRes.success) {
            const medicalAction = medicalRes.data;
            
            // Mettre à jour le formulaire avec les données
            formik.setValues({
              animal: medicalAction.animalId || medicalAction.animal?._id || medicalAction.animal?.id || '',
              type: medicalAction.type || 'vaccination',
              name: medicalAction.name || '',
              date: medicalAction.date ? format(new Date(medicalAction.date), 'yyyy-MM-dd') : '',
              notes: medicalAction.notes || '',
              nextDueDate: medicalAction.nextDueDate ? format(new Date(medicalAction.nextDueDate), 'yyyy-MM-dd') : '',
              frequency: medicalAction.frequency || 12,
            });
            
            // Mettre à jour l'animal sélectionné
            if (medicalAction.animal) {
              setSelectedAnimal(medicalAction.animal);
            }
            
            // Mettre à jour l'état du switch
            setHasNextDueDate(!!medicalAction.nextDueDate);
          }
        }
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, [id, isEdit]);

  // Mettre à jour l'animal sélectionné lorsque l'ID change
  useEffect(() => {
    const updateSelectedAnimal = async () => {
      if (formik.values.animal) {
        try {
          const animalRes = await getAnimalById(formik.values.animal);
          if (animalRes && animalRes.data) setSelectedAnimal(animalRes.data);
        } catch (error) {
          console.error('Error fetching animal:', error);
        }
      } else {
        setSelectedAnimal(null);
      }
    };
    
    updateSelectedAnimal();
  }, [formik.values.animal]);

  // Calculer la prochaine date en fonction de la fréquence
  const calculateNextDueDate = () => {
    if (formik.values.date && formik.values.frequency) {
      const nextDate = addMonths(new Date(formik.values.date), parseInt(formik.values.frequency));
      formik.setFieldValue('nextDueDate', format(nextDate, 'yyyy-MM-dd'));
    }
  };

  useEffect(() => {
    if (isEdit) return;
    if (formik.values.type === 'vaccination') {
      setHasNextDueDate(true);
      if (!formik.values.nextDueDate) calculateNextDueDate();
    } else {
      setHasNextDueDate(false);
      formik.setFieldValue('nextDueDate', '');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formik.values.type, isEdit]);

  // Gérer le changement du switch pour la prochaine date
  const handleNextDueDateToggle = (event) => {
    setHasNextDueDate(event.target.checked);
    if (event.target.checked && !formik.values.nextDueDate) {
      calculateNextDueDate();
    }
  };

  // Gérer la suppression
  const handleDelete = () => {
    setDeleteDialogOpen(true);
  };

  // Confirmer la suppression
  const confirmDelete = async () => {
    try {
      setLoading(true);
      // Appel API pour supprimer
      // await deleteMedicalAction(id);
      navigate('/medical');
    } catch (error) {
      console.error('Error deleting medical action:', error);
    } finally {
      setLoading(false);
      setDeleteDialogOpen(false);
    }
  };

  return (
    <Box>
      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <IconButton 
            component={Link} 
            to="/medical"
            sx={{ mr: 1 }}
          >
            <ArrowBackIcon />
          </IconButton>
          <Typography variant="h5">
            {isEdit ? 'Edit Medical Action' : 'New Medical Action'}
          </Typography>
        </Box>
        {isEdit && (
          <Button 
            variant="outlined" 
            color="error" 
            startIcon={<DeleteIcon />}
            onClick={handleDelete}
          >
            Delete
          </Button>
        )}
      </Box>

      <Paper elevation={2} sx={{ p: 3, borderRadius: 2 }}>
        {loading ? (
          <Box display="flex" justifyContent="center" p={3}>
            <CircularProgress />
          </Box>
        ) : (
          <form onSubmit={formik.handleSubmit}>
            <Grid container spacing={3}>
              {/* Informations de base */}
              <Grid item xs={12}>
                <Typography variant="h6" color="primary" sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <MedicalIcon sx={{ mr: 1 }} />
                  Basic Information
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={8}>
                    <FormControl fullWidth sx={{ minWidth: 220 }} error={formik.touched.animal && Boolean(formik.errors.animal)}>
                      <InputLabel id="animal-label">Animal</InputLabel>
                      <Select
                        labelId="animal-label"
                        id="animal"
                        name="animal"
                        value={formik.values.animal}
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                        label="Animal"
                      >
                        {animals.map((animal) => (
                          <MenuItem key={animal._id} value={animal._id}>
                            {animal.name}
                          </MenuItem>
                        ))}
                      </Select>
                      {formik.touched.animal && formik.errors.animal && (
                        <FormHelperText>{formik.errors.animal}</FormHelperText>
                      )}
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <FormControl fullWidth error={formik.touched.type && Boolean(formik.errors.type)}>
                      <InputLabel id="type-label">Type</InputLabel>
                      <Select
                        labelId="type-label"
                        id="type"
                        name="type"
                        value={formik.values.type}
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                        label="Type"
                      >
                        <MenuItem value="vaccination">Vaccination</MenuItem>
                        <MenuItem value="treatment">Treatment</MenuItem>
                        <MenuItem value="checkup">Checkup</MenuItem>
                        <MenuItem value="other">Other</MenuItem>
                      </Select>
                      {formik.touched.type && formik.errors.type && (
                        <FormHelperText>{formik.errors.type}</FormHelperText>
                      )}
                    </FormControl>
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      id="name"
                      name="name"
                      label="Medical Action Name"
                      value={formik.values.name}
                      onChange={formik.handleChange}
                      onBlur={formik.handleBlur}
                      error={formik.touched.name && Boolean(formik.errors.name)}
                      helperText={formik.touched.name && formik.errors.name}
                      placeholder="Ex: Rabies vaccine, Parasite treatment..."
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      id="date"
                      name="date"
                      label="Date"
                      type="date"
                      value={formik.values.date}
                      onChange={(e) => {
                        formik.handleChange(e);
                        if (hasNextDueDate) {
                          calculateNextDueDate();
                        }
                      }}
                      onBlur={formik.handleBlur}
                      error={formik.touched.date && Boolean(formik.errors.date)}
                      helperText={formik.touched.date && formik.errors.date}
                      InputLabelProps={{ shrink: true }}
                    />
                  </Grid>
                </Grid>
              </Grid>

              <Grid item xs={12}>
                <Divider />
              </Grid>

              {/* Scheduling Section */}
              <Grid item xs={12}>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <Typography variant="h6" color="primary" sx={{ display: 'flex', alignItems: 'center', flexGrow: 1 }}>
                    <CalendarIcon sx={{ mr: 1 }} />
                    Scheduling
                  </Typography>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={hasNextDueDate}
                        onChange={handleNextDueDateToggle}
                        color="primary"
                      />
                    }
                    label="Schedule next action"
                  />
                </Box>
                
                {hasNextDueDate && (
                  <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                      <TextField
                        fullWidth
                        id="frequency"
                        name="frequency"
                        label="Frequency (months)"
                        type="number"
                        value={formik.values.frequency}
                        onChange={(e) => {
                          formik.handleChange(e);
                          calculateNextDueDate();
                        }}
                        onBlur={formik.handleBlur}
                        error={formik.touched.frequency && Boolean(formik.errors.frequency)}
                        helperText={formik.touched.frequency && formik.errors.frequency}
                        InputProps={{ inputProps: { min: 1 } }}
                      />
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <TextField
                        fullWidth
                        id="nextDueDate"
                        name="nextDueDate"
                        label="Next due date"
                        type="date"
                        value={formik.values.nextDueDate}
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                        error={formik.touched.nextDueDate && Boolean(formik.errors.nextDueDate)}
                        helperText={formik.touched.nextDueDate && formik.errors.nextDueDate}
                        InputLabelProps={{ shrink: true }}
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <Button
                        variant="outlined"
                        size="small"
                        onClick={calculateNextDueDate}
                        startIcon={<CalendarIcon />}
                      >
                        Calculate next date
                      </Button>
                    </Grid>
                  </Grid>
                )}
                
                {!hasNextDueDate && (
                  <Alert severity="info" sx={{ mt: 1 }}>
                    Enable this option to schedule reminders for periodic vaccinations or treatments.
                  </Alert>
                )}
              </Grid>

              <Grid item xs={12}>
                <Divider />
              </Grid>

              {/* Notes */}
              <Grid item xs={12}>
                <Typography variant="h6" color="primary" sx={{ mb: 2 }}>
                  Notes
                </Typography>
                <TextField
                  fullWidth
                  id="notes"
                  name="notes"
                  label="Additional notes"
                  multiline
                  rows={4}
                  value={formik.values.notes}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  error={formik.touched.notes && Boolean(formik.errors.notes)}
                  helperText={formik.touched.notes && formik.errors.notes}
                  placeholder="Add details about the medical action..."
                />
              </Grid>

              {/* Buttons */}
              <Grid item xs={12} sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
                <Button
                  component={Link}
                  to="/medical"
                  variant="outlined"
                  sx={{ mr: 1 }}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  variant="contained"
                  startIcon={<SaveIcon />}
                  disabled={loading}
                >
                  {loading ? <CircularProgress size={24} /> : 'Save'}
                </Button>
              </Grid>
            </Grid>
          </form>
        )}
      </Paper>

      {/* Dialogue de confirmation de suppression */}
      <ConfirmationDialog
        open={deleteDialogOpen}
        title="Delete Medical Action"
        content="Are you sure you want to delete this medical action? This action cannot be undone."
        onConfirm={confirmDelete}
        onClose={() => setDeleteDialogOpen(false)}
      />
    </Box>
  );
};

export default MedicalForm;
