import React, { useState } from 'react';
import { 
  Button, 
  Dialog, 
  DialogActions, 
  DialogContent, 
  DialogContentText, 
  DialogTitle,
  CircularProgress,
  Alert,
  Typography,
  Box
} from '@mui/material';
import { 
  DeleteForever as DeleteIcon,
  Warning as WarningIcon
} from '@mui/icons-material';
import { clearDatabase } from '../../utils/clearDatabase';

const ClearDatabaseButton = () => {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [confirmText, setConfirmText] = useState('');

  const handleOpen = () => {
    setOpen(true);
    setResults(null);
    setSuccess(false);
    setError('');
    setConfirmText('');
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleClearDatabase = async () => {
    try {
      setLoading(true);
      setSuccess(false);
      setError('');
      setResults(null);
      
      const clearResults = await clearDatabase();
      setResults(clearResults);
      
      if (clearResults.animals.success && clearResults.feedings.success) {
        setSuccess(true);
      } else {
        setError('Some collections failed to clear. Check the console for details.');
      }
    } catch (err) {
      console.error('Error clearing database:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const isConfirmValid = confirmText === 'DELETE ALL';

  return (
    <>
      <Button 
        variant="outlined" 
        color="error" 
        onClick={handleOpen}
        startIcon={<DeleteIcon />}
        sx={{ ml: 2 }}
      >
        Clear Database
      </Button>
      
      <Dialog 
        open={open} 
        onClose={handleClose}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle sx={{ display: 'flex', alignItems: 'center' }}>
          <WarningIcon color="error" sx={{ mr: 1 }} />
          Clear Entire Database
        </DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ mb: 2, color: 'error.main', fontWeight: 'bold' }}>
            WARNING: This action will permanently delete ALL animals and feeding records from your database.
            This operation CANNOT be undone!
          </DialogContentText>
          
          <Typography variant="body2" sx={{ mb: 3 }}>
            To confirm, please type "DELETE ALL" in the field below:
          </Typography>
          
          <input
            type="text"
            value={confirmText}
            onChange={(e) => setConfirmText(e.target.value)}
            placeholder="Type DELETE ALL to confirm"
            style={{
              width: '100%',
              padding: '10px',
              border: '1px solid #ccc',
              borderRadius: '4px',
              fontSize: '16px'
            }}
          />
          
          {loading && (
            <Box display="flex" justifyContent="center" my={3}>
              <CircularProgress />
            </Box>
          )}
          
          {success && (
            <Alert severity="success" sx={{ mt: 2 }}>
              Database cleared successfully!
              <Typography variant="body2">
                Deleted {results.animals.count} animals and {results.feedings.count} feeding records.
              </Typography>
            </Alert>
          )}
          
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button 
            onClick={handleClearDatabase} 
            color="error" 
            disabled={loading || !isConfirmValid}
            startIcon={loading ? <CircularProgress size={20} /> : <DeleteIcon />}
            variant="contained"
          >
            {loading ? 'Clearing...' : 'Clear Database'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default ClearDatabaseButton;
