// Fonction pour ajouter un animal à Firestore
const addAnimal = async (animalData) => {
  try {
    // Récupérer une image par défaut pour l'espèce
    const defaultImage = await getDefaultImageForSpecies(animalData.species);
    
    const animalToSave = {
      ...animalData,
      notes: `${animalData.name} is a ${animalData.species}.`,
      image: defaultImage, // Ajouter l'image par défaut
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp()
    };
    
    const docRef = await addDoc(collection(db, 'animals'), animalToSave);
    console.log(`Animal ${animalData.name} added with ID: ${docRef.id}`);
    return docRef.id;
  } catch (error) {
    console.error(`Error adding animal ${animalData.name}:`, error);
    throw error;
  }
};

// Fonction pour initialiser tous les animaux
export const initializeAnimals = async () => {
  console.log('Starting animal initialization...');
  const results = [];
  
  // Traiter les animaux par lots pour éviter de surcharger le navigateur avec trop de requêtes d'images
  const batchSize = 5;
  for (let i = 0; i < animalsList.length; i += batchSize) {
    const batch = animalsList.slice(i, i + batchSize);
    const batchPromises = batch.map(async (animal) => {
      try {
        const id = await addAnimal(animal);
        return { name: animal.name, id, success: true };
      } catch (error) {
        return { name: animal.name, success: false, error: error.message };
      }
    });
    
    const batchResults = await Promise.all(batchPromises);
    results.push(...batchResults);
    
    // Petite pause entre les lots pour éviter de surcharger le navigateur
    if (i + batchSize < animalsList.length) {
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
  }
  
  console.log('Animal initialization completed!');
  return results;
};

export default initializeAnimals;
