import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Button, 
  TextField, 
  Typography, 
  Paper, 
  Grid, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  FormHelperText,
  CircularProgress,
  Avatar,
  IconButton,
  Divider,
  useTheme,
  Tooltip,
} from '@mui/material';
import { 
  Save as SaveIcon, 
  ArrowBack as ArrowBackIcon,
  Delete as DeleteIcon,
  CameraAlt as CameraAltIcon,
} from '@mui/icons-material';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import { getAnimalById, createAnimal, updateAnimal } from '../api/api';
import ConfirmationDialog from '../components/common/ConfirmationDialog';
import { compressImageByType } from '../utils/imageCompression';

const validationSchema = Yup.object({
  name: Yup.string().required('Name is required'),
  species: Yup.string().required('Species is required'),
  // Status supprimé
});

const AnimalForm = ({ isEdit = false }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const theme = useTheme();
  const [loading, setLoading] = useState(isEdit);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [imagePreview, setImagePreview] = useState(null);
  const [imageFile, setImageFile] = useState(null);

  // Nettoyer l'URL objet du preview quand il change ou au démontage
  useEffect(() => {
    return () => {
      if (imagePreview && typeof imagePreview === 'string' && imagePreview.startsWith('blob:')) {
        URL.revokeObjectURL(imagePreview);
      }
    };
  }, [imagePreview]);

  const formik = useFormik({
    initialValues: {
      name: '',
      species: '',
      dateOfBirth: '',
      dateOfArrival: '',
      gender: 'unknown',
      // Status supprimé, toujours actif par défaut
      notes: '',
    },
    validationSchema,
    onSubmit: async (values) => {
      try {
        setLoading(true);
        
        // Préparer les données de l'animal
        const animalData = {
          name: values.name,
          species: values.species,
          status: 'active', // Toujours actif par défaut
          notes: values.notes || '',
          dateOfBirth: values.dateOfBirth || null,
          dateOfArrival: values.dateOfArrival || null,
          gender: values.gender || 'unknown',
        };
        
        // Gestion de l'image
        if (imageFile) {
          // Nouvelle image uploadée
          animalData.image = imageFile;
          console.log('Nouvelle image à uploader');
        } else if (isEdit && values.removeImage) {
          // Suppression de l'image existante
          animalData.image = null;
          console.log('Suppression de l\'image');
        } else if (isEdit && imagePreview && !imagePreview.startsWith('blob:')) {
          // Image existante non modifiée (conserver l'image existante)
          animalData.image = imagePreview;
          console.log('Conservation de l\'image existante');
        }
        
        let response;
        if (isEdit) {
          response = await updateAnimal(id, animalData);
        } else {
          response = await createAnimal(animalData);
        }
        
        navigate('/animals');
      } catch (error) {
        console.error('Error saving animal:', error);
      } finally {
        setLoading(false);
      }
    },
  });

  useEffect(() => {
    if (isEdit && id) {
      const fetchAnimal = async () => {
        try {
          setLoading(true);
          const response = await getAnimalById(id);
          const animal = response.data;
          
          formik.setValues({
            name: animal.name || '',
            species: animal.species || '',
            dateOfBirth: animal.dateOfBirth ? String(animal.dateOfBirth).slice(0, 10) : '',
            dateOfArrival: animal.dateOfArrival ? String(animal.dateOfArrival).slice(0, 10) : '',
            gender: animal.gender || 'unknown',
            // Status supprimé
            notes: animal.notes || '',
          });
          
          if (animal.image) {
            // L'image est déjà en base64 dans Firebase
            setImagePreview(animal.image);
          }
        } catch (error) {
          console.error('Error fetching animal:', error);
          navigate('/animals');
        } finally {
          setLoading(false);
        }
      };
      
      fetchAnimal();
    }
  }, [id, isEdit, navigate]);

  const handleImageChange = async (event) => {
    const file = event.target.files[0];
    if (file) {
      try {
        // Aperçu immédiat et robuste (JPG inclus) via URL.createObjectURL
        const immediatePreviewUrl = URL.createObjectURL(file);
        setImagePreview(immediatePreviewUrl);
        
        // Compresser l'image en arrière-plan
        console.log('Compression de l\'image de profil...');
        const compressedImage = await compressImageByType(file, 'profile');
        setImageFile(compressedImage);
        // Mettre à jour le preview pour refléter l'image compressée
        const compressedPreviewUrl = URL.createObjectURL(compressedImage);
        setImagePreview((prev) => {
          if (prev && prev.startsWith('blob:')) URL.revokeObjectURL(prev);
          return compressedPreviewUrl;
        });
        console.log('Image compressée avec succès');
      } catch (error) {
        console.error('Erreur lors de la compression de l\'image:', error);
        // En cas d'échec, utiliser l'image originale
        setImageFile(file);
      }
    }
  };

  const handleRemoveImage = () => {
    setImagePreview(null);
    setImageFile(null);
    // In edit mode, we need to send a signal to remove the existing image
    if (isEdit) {
      formik.setFieldValue('removeImage', true);
    }
  };

  const handleDeleteClick = () => {
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = () => {
    // Handle delete logic here
    console.log('Deleting animal:', id);
    setDeleteDialogOpen(false);
    navigate('/animals');
  };

  if (loading && isEdit) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      {/* Header avec titre et bouton retour */}
      <Box display="flex" alignItems="center" mb={3}>
        <IconButton component={Link} to="/animals" sx={{ mr: 1 }}>
          <ArrowBackIcon />
        </IconButton>
        <Typography variant="h5" component="h1">
          {isEdit ? 'Edit Animal' : 'Add New Animal'}
        </Typography>
      </Box>

      <Paper elevation={2} sx={{ p: 3, borderRadius: 2 }}>
        <form onSubmit={formik.handleSubmit}>
          <Grid container spacing={3}>
            <Grid item xs={12} md={4}>
              <Box 
                display="flex" 
                flexDirection="column" 
                alignItems="center"
                mb={2}
              >
                <Box
                  sx={{
                    width: 200,
                    height: 200,
                    borderRadius: '50%',
                    backgroundColor: theme.palette.grey[200],
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    overflow: 'hidden',
                    position: 'relative',
                    mb: 2,
                    border: '1px solid',
                    borderColor: 'divider',
                  }}
                >
                  {imagePreview ? (
                    <img
                      src={imagePreview}
                      alt="Animal preview"
                      style={{
                        width: '100%',
                        height: '100%',
                        objectFit: 'cover',
                      }}
                    />
                  ) : (
                    <CameraAltIcon sx={{ fontSize: 48, color: theme.palette.grey[500] }} />
                  )}
                  <input
                    accept="image/jpeg,image/jpg,image/png,image/webp,image/heic,image/heif"
                    id="animal-image-upload"
                    type="file"
                    onChange={handleImageChange}
                    style={{ display: 'none' }}
                  />
                  <label htmlFor="animal-image-upload">
                    <Box
                      sx={{
                        position: 'absolute',
                        bottom: 0,
                        left: 0,
                        right: 0,
                        backgroundColor: 'rgba(0, 0, 0, 0.5)',
                        color: 'white',
                        textAlign: 'center',
                        padding: '8px',
                        cursor: 'pointer',
                        '&:hover': {
                          backgroundColor: 'rgba(0, 0, 0, 0.7)',
                        },
                      }}
                    >
                      <CameraAltIcon fontSize="small" sx={{ mr: 0.5 }} />
                      {imagePreview ? 'Change' : 'Upload'} Photo
                    </Box>
                  </label>
                </Box>
                
                <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center', mb: 2 }}>
                  <Tooltip title="L'image sera fortement compressée pour un chargement rapide">
                    <label htmlFor="animal-image-upload">
                      <Button
                        variant="outlined"
                        component="span"
                        startIcon={<CameraAltIcon />}
                        size="small"
                      >
                        {imagePreview ? 'Change' : 'Upload'} Image
                      </Button>
                    </label>
                  </Tooltip>
                  
                  {imagePreview && (
                    <Button
                      variant="outlined"
                      color="error"
                      size="small"
                      startIcon={<DeleteIcon />}
                      onClick={handleRemoveImage}
                    >
                      Remove
                    </Button>
                  )}
                </Box>
                
                <FormHelperText sx={{ textAlign: 'center' }}>
                  Recommended size: 500x500px
                </FormHelperText>
              </Box>
            </Grid>
            
            <Grid item xs={12} md={8}>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    id="name"
                    name="name"
                    label="Animal Name"
                    value={formik.values.name}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.name && Boolean(formik.errors.name)}
                    helperText={formik.touched.name && formik.errors.name}
                    margin="normal"
                    variant="outlined"
                    size="small"
                  />
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    id="species"
                    name="species"
                    label="Species"
                    value={formik.values.species}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.species && Boolean(formik.errors.species)}
                    helperText={formik.touched.species && formik.errors.species}
                    margin="normal"
                    variant="outlined"
                    size="small"
                  />
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    id="dateOfBirth"
                    name="dateOfBirth"
                    label="Date of Birth"
                    type="date"
                    value={formik.values.dateOfBirth}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    margin="normal"
                    variant="outlined"
                    size="small"
                    InputLabelProps={{ shrink: true }}
                  />
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    id="dateOfArrival"
                    name="dateOfArrival"
                    label="Date of Arrival"
                    type="date"
                    value={formik.values.dateOfArrival}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    margin="normal"
                    variant="outlined"
                    size="small"
                    InputLabelProps={{ shrink: true }}
                  />
                </Grid>

                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth margin="normal" size="small">
                    <InputLabel id="gender-label">Gender</InputLabel>
                    <Select
                      labelId="gender-label"
                      id="gender"
                      name="gender"
                      value={formik.values.gender}
                      onChange={formik.handleChange}
                      onBlur={formik.handleBlur}
                      label="Gender"
                    >
                      <MenuItem value="unknown">Unknown</MenuItem>
                      <MenuItem value="male">Male</MenuItem>
                      <MenuItem value="female">Female</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                
                
                {/* Champ de statut supprimé */}
                
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    id="notes"
                    name="notes"
                    label="Notes"
                    multiline
                    rows={4}
                    value={formik.values.notes}
                    onChange={formik.handleChange}
                    margin="normal"
                    variant="outlined"
                    size="small"
                  />
                </Grid>
                
                {/* Barre d'actions avec tous les boutons regroupés */}
                <Grid item xs={12}>
                  <Divider sx={{ my: 2 }} />
                  <Box display="flex" justifyContent="space-between" alignItems="center">
                    {/* Boutons à gauche */}
                    <Box>
                      {isEdit && (
                        <Button
                          variant="outlined"
                          color="error"
                          startIcon={<DeleteIcon />}
                          onClick={handleDeleteClick}
                          sx={{ mr: 1 }}
                        >
                          Delete Animal
                        </Button>
                      )}
                    </Box>
                    
                    {/* Boutons à droite */}
                    <Box display="flex" gap={2}>
                      <Button
                        variant="outlined"
                        color="inherit"
                        onClick={() => navigate('/animals')}
                        disabled={loading}
                      >
                        Cancel
                      </Button>
                      <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <SaveIcon />}
                        disabled={loading}
                      >
                        {isEdit ? 'Update' : 'Create'} Animal
                      </Button>
                    </Box>
                  </Box>
                </Grid>
              </Grid>
            </Grid>
          </Grid>
        </form>
      </Paper>

      <ConfirmationDialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Delete Animal"
        content="Are you sure you want to delete this animal? This action cannot be undone."
        confirmText="Delete"
        confirmColor="error"
      />
    </Box>
  );
};

export default AnimalForm;
